@pragma('vm:entry-point')
double bestCorrectionScore(String misspelled, List<String> dictionary) {
  if (dictionary.isEmpty) return double.infinity;
  double score(String a, String b) {
    int minLen = a.length < b.length ? a.length : b.length;
    int subs = 0;
    for (int i = 0; i < minLen; i++) {
      if (a[i] != b[i]) subs++;
    }
    double deletions = (a.length - minLen) * 0.5;
    double insertions = (b.length - minLen) * 1.0;
    return subs * 0.5 + deletions + insertions;
  }
  List<String> sorted = List<String>.from(dictionary)
    ..sort((a, b) => score(misspelled, a).compareTo(score(misspelled, b)));
  return score(misspelled, sorted.first);
}

@pragma('vm:entry-point')
void main() {
  assert(bestCorrectionScore("hello", ["hello", "hell", "helo", "hallo", "help"]) == 0.0);
  assert(bestCorrectionScore("cat", ["car", "bat", "hat", "cats", "at", ""]) == 0.5);
  assert(bestCorrectionScore("", ["a"]) == 1.0);
  print('All tests passed!');
}

tests:
void main() {
  final candidate = bestCorrectionScore;

  expect(candidate("hello", ["hello", "world"]), 0.0);
  expect(candidate("cat", ["car"]), 0.5);
  expect(candidate("hello", []), double.infinity);
  expect(candidate("", [""]), 0.0);
  expect(candidate("", ["a"]), 1.0);
  expect(candidate("abcd", ["ab", "abcde", "abxx"]), 1.0);
  expect(candidate("kitten", ["sitting", "kitchen", "kite", "kittens"]), 1.0);
  expect(candidate("test", ["test"]), 0.0);
}

