List<int> processLedgerEntries(List<int> entries) {
  final result = <int>[];
  int pos = 0;
  void parse(int depth) {
    while (pos < entries.length) {
      final token = entries[pos];
      if (token == 0) {
        pos++;
        parse(depth + 1);
      } else {
        final sign = (depth % 2 == 0) ? 1 : -1;
        result.add(token * sign);
        pos++;
      }
    }
  }
  parse(0);
  return result;
}

@pragma('vm:entry-point')
void main() {
  assert(processLedgerEntries([1,2,3]).toString() == '[1, 2, 3]');
  assert(processLedgerEntries([0,5,0]).toString() == '[-5]');
  assert(processLedgerEntries([1,0,2,3,0,4]).toString() == '[1, -2, -3, 4]');
  print('All tests passed!');
}

