int countEmptyFlaggedBins(int inventoryMask, int flaggedMask) {
  const int allBins = 0xFFFFFFFF;
  int empty = (~inventoryMask) & allBins;
  int flagged = flaggedMask & allBins;
  int needRestock = empty & flagged;
  int count = 0;
  while (needRestock != 0) {
    needRestock &= needRestock - 1;
    count++;
  }
  return count;
}

