@pragma('vm:entry-point')
String knightReachableSquares(String start, int moves) {
  Set<String> visited = {};

  void dfs(String pos, int remaining) {
    if (remaining == 0) {
      visited.add(pos);
      return;
    }
    int c = pos.codeUnitAt(0) - 'a'.codeUnitAt(0) + 1;
    int r = int.parse(pos[1]);
    List<List<int>> knightMoves = [
      [1, 2], [1, -2], [-1, 2], [-1, -2],
      [2, 1], [2, -1], [-2, 1], [-2, -1]
    ];
    for (List<int> move in knightMoves) {
      int nc = c + move[0];
      int nr = r + move[1];
      if (nc >= 1 && nc <= 8 && nr >= 1 && nr <= 8) {
        String nextPos = '${String.fromCharCode('a'.codeUnitAt(0) + nc - 1)}$nr';
        dfs(nextPos, remaining - 1);
      }
    }
  }

  dfs(start, moves);
  List<String> result = visited.toList()..sort();
  return result.join(',');
}

@pragma('vm:entry-point')
void main() {
  assert(knightReachableSquares('a1', 0) == 'a1');
  assert(knightReachableSquares('a1', 1) == 'b3,c2');
  assert(knightReachableSquares('h8', 1) == 'f7,g6');
  print('All tests passed!');
}

tests:
void main() {
  final candidate = knightReachableSquares;

  expect(candidate('a1', 0), 'a1');
  expect(candidate('a1', 1), 'b3,c2');
  expect(candidate('e4', 1), 'c3,c5,d2,d6,f2,f6,g3,g5');
  expect(candidate('a1', 2), 'a1,a3,a5,b4,c1,c5,d2,d4,e1,e3');
  expect(candidate('h8', 1), 'f7,g6');
  expect(candidate('d4', 0), 'd4');
  expect(candidate('a8', 1), 'b6,c7');
  expect(candidate('h1', 1), 'f2,g3');
}

