  final candidate = sortAsciiRowsByAlignment;

  expect(candidate(["  hello", "hello", "   hi"]).toString(), "[hello,   hello,    hi]");
  expect(candidate([" abc", " a", " ab"]).toString(), "[ abc,  ab,  a]");
  expect(candidate(["  ab", "  cd"]).toString(), "[  ab,   cd]");
  expect(candidate([]).toString(), "[]");
  expect(candidate(["hello", "world"]).toString(), "[hello, world]");
  expect(candidate(["z", "a"]).toString(), "[a, z]");
  expect(candidate(["*", " * ", "  *"]).toString(), "[*,  * ,   *]");
  expect(candidate(["only one"]).toString(), "[only one]");
  expect(candidate(["b", "a", "c"]).toString(), "[a, b, c]");
}

