List<String> sortTimetableByMinute(List<int> departures) {
  final sorted = List<int>.from(departures);
  sorted.sort((a, b) {
    final minuteA = a % 60;
    final minuteB = b % 60;
    if (minuteA != minuteB) return minuteA.compareTo(minuteB);
    return (a ~/ 60).compareTo(b ~/ 60);
  });
  return sorted.map((m) {
    final h = (m ~/ 60).toString().padLeft(2, '0');
    final min = (m % 60).toString().padLeft(2, '0');
    return '$h:$min';
  }).toList();
}

