@pragma('vm:entry-point')
Map<String, int> auditBatteryChargeCycles(List<int> changes, int capacity) {
  if (capacity <= 0) {
    return {'cycles': 0, 'finalCharge': 0, 'spilled': 0, 'emptyHits': 0};
  }

  Map<String, int> step(
    int index,
    int charge,
    int cycles,
    int spilled,
    int emptyHits,
  ) {
    if (index == changes.length) {
      return {
        'cycles': cycles,
        'finalCharge': charge,
        'spilled': spilled,
        'emptyHits': emptyHits,
      };
    }

    int delta = changes[index];
    int nextCharge = charge;
    int nextCycles = cycles;
    int nextSpilled = spilled;
    int nextEmptyHits = emptyHits;

    if (delta >= 0) {
      int filled = charge + delta;
      if (filled >= capacity) {
        if (charge < capacity && delta > 0) {
          nextCycles++;
        }
        nextSpilled += filled - capacity;
        nextCharge = capacity;
      } else {
        nextCharge = filled;
      }
    } else {
      int drained = charge + delta;
      if (drained <= 0) {
        nextCharge = 0;
        nextEmptyHits++;
      } else {
        nextCharge = drained;
      }
    }

    return step(index + 1, nextCharge, nextCycles, nextSpilled, nextEmptyHits);
  }

  return step(0, 0, 0, 0, 0);
}

@pragma('vm:entry-point')
void main() {
  assert(auditBatteryChargeCycles([3, 7], 10)['cycles'] == 1);
  assert(auditBatteryChargeCycles([-1], 10)['emptyHits'] == 1);
  assert(auditBatteryChargeCycles([12, 4], 10).toString() == '{cycles: 1, finalCharge: 10, spilled: 6, emptyHits: 0}');
  print('All tests passed!');
}

