Set<int> possibleInstantRunoffWinners(List<List<int>> tallyRows) {
  final all = <int>{};
  for (final row in tallyRows) {
    final seen = <int>{};
    for (var i = 1; i < row.length; i++) { if (seen.add(row[i])) all.add(row[i]); }
  }
  final memo = <String, Set<int>>{};
  String keyOf(Set<int> s) { final ids = s.toList()..sort(); return ids.join(','); }
  Set<int> search(Set<int> active) {
    if (active.isEmpty) return <int>{};
    if (active.length == 1) return <int>{active.first};
    final key = keyOf(active);
    final cached = memo[key];
    if (cached != null) return Set<int>.from(cached);
    final counts = <int, int>{for (final c in active) c: 0};
    var liveVotes = 0;
    for (final row in tallyRows) {
      if (row.isEmpty || row[0] <= 0) continue;
      final seen = <int>{};
      for (var i = 1; i < row.length; i++) {
        final c = row[i];
        if (!seen.add(c)) continue;
        if (active.contains(c)) { counts[c] = counts[c]! + row[0]; liveVotes += row[0]; break; }
      }
    }
    for (final c in active) {
      if (liveVotes > 0 && counts[c]! * 2 > liveVotes) { memo[key] = <int>{c}; return <int>{c}; }
    }
    var low = counts[active.first]!;
    for (final c in active) { if (counts[c]! < low) low = counts[c]!; }
    final winners = <int>{};
    final tiedLow = active.where((c) => counts[c] == low).toList()..sort();
    for (final loser in tiedLow) {
      final next = Set<int>.from(active)..remove(loser);
      winners.addAll(search(next));
    }
    memo[key] = Set<int>.from(winners);
    return winners;
  }
  return search(all);
}

