List<String> kthComfortMinutesInThermostatSchedule(List<int> starts, List<int> ends, List<int> heatLevels, int comfortLevel, List<int> requests) {
  int n = starts.length;
  if (ends.length < n) n = ends.length;
  if (heatLevels.length < n) n = heatLevels.length;

  List<List<int>> events = <List<int>>[];
  for (int i = 0; i < n; i++) {
    int a = starts[i];
    int b = ends[i];
    int h = heatLevels[i];
    if (b <= a) continue;
    events.add(<int>[a, h]);
    events.add(<int>[b, -h]);
  }

  List<String> answers = <String>[];
  if (events.isEmpty) {
    for (int k in requests) {
      answers.add('$k:none');
    }
    return answers;
  }

  events.sort((List<int> x, List<int> y) {
    int byTime = x[0].compareTo(y[0]);
    if (byTime != 0) return byTime;
    return x[1].compareTo(y[1]);
  });

  List<int> spanStarts = <int>[];
  List<int> prefixEnds = <int>[];
  int activeHeat = 0;
  int lastTime = events[0][0];
  int covered = 0;
  int i = 0;

  while (i < events.length) {
    int time = events[i][0];
    if (time > lastTime && activeHeat >= comfortLevel) {
      spanStarts.add(lastTime);
      covered += time - lastTime;
      prefixEnds.add(covered);
    }
    while (i < events.length && events[i][0] == time) {
      activeHeat += events[i][1];
      i++;
    }
    lastTime = time;
  }

  for (int k in requests) {
    if (k <= 0 || k > covered) {
      answers.add('$k:none');
      continue;
    }
    int lo = 0;
    int hi = prefixEnds.length - 1;
    while (lo < hi) {
      int mid = lo + ((hi - lo) >> 1);
      if (prefixEnds[mid] >= k) {
        hi = mid;
      } else {
        lo = mid + 1;
      }
    }
    int before = lo == 0 ? 0 : prefixEnds[lo - 1];
    int minute = spanStarts[lo] + k - before - 1;
    answers.add('$k:$minute');
  }
  return answers;
}

