@pragma('vm:entry-point')
Map<String, int> analyzeStatusCodeFamilies(List<String> logLines) {
  final counts = <String, int>{'2xx': 0, '3xx': 0, '4xx': 0, '5xx': 0};
  for (final line in logLines) {
    final parts = line.split(' ');
    if (parts.length >= 2) {
      final code = int.tryParse(parts[0]);
      if (code != null && code >= 200 && code < 600) {
        final family = '${code ~/ 100}xx';
        counts[family] = (counts[family] ?? 0) + 1;
      }
    }
  }
  int gcd = 0;
  for (final count in counts.values) {
    if (count > 0) {
      int a = gcd == 0 ? count : gcd, b = count;
      while (b != 0) { final t = b; b = a % b; a = t; }
      gcd = a;
    }
  }
  counts['gcd'] = gcd;
  counts.removeWhere((k, v) => v == 0 && k != 'gcd');
  return counts;
}

@pragma('vm:entry-point')
void main() {
  assert(analyzeStatusCodeFamilies([])['gcd'] == 0);
  assert(analyzeStatusCodeFamilies(['200 /api'])['gcd'] == 1);
  assert(analyzeStatusCodeFamilies(['200 /a', '404 /b', '404 /c'])['4xx'] == 2);
  print('All tests passed!');
}

