@pragma('vm:entry-point')
List<int> sortDiceGameRounds(List<int> rounds) {
  rounds.sort((a, b) {
    int a1 = a ~/ 10, a2 = a % 10;
    int b1 = b ~/ 10, b2 = b % 10;
    int sumA = a1 + a2, sumB = b1 + b2;
    if (sumA != sumB) return sumB - sumA;
    bool doubleA = a1 == a2, doubleB = b1 == b2;
    if (doubleA != doubleB) return doubleA ? -1 : 1;
    int maxA = a1 > a2 ? a1 : a2, maxB = b1 > b2 ? b1 : b2;
    return maxB - maxA;
  });
  return rounds;
}

