@pragma('vm:entry-point')
String largestUniformSquareArea(List<String> art) {
  if (art.isEmpty || art[0].isEmpty) return '0';
  int rows = art.length, cols = art[0].length, maxSide = 1;
  var dp = List.generate(rows, (_) => List<int>.filled(cols, 1));
  for (int i = 1; i < rows; i++) {
    for (int j = 1; j < cols; j++) {
      if (art[i][j] == art[i-1][j] && art[i][j] == art[i][j-1] && art[i][j] == art[i-1][j-1]) {
        int m = dp[i-1][j];
        if (dp[i][j-1] < m) m = dp[i][j-1];
        if (dp[i-1][j-1] < m) m = dp[i-1][j-1];
        dp[i][j] = m + 1;
        if (dp[i][j] > maxSide) maxSide = dp[i][j];
      }
    }
  }
  return '${maxSide * maxSide}';
}

@pragma('vm:entry-point')
void main() {
  assert(largestUniformSquareArea([]) == '0');
  assert(largestUniformSquareArea(['X']) == '1');
  assert(largestUniformSquareArea(['AA','AA']) == '4');
