  expect(candidate(3, []), true);
  expect(candidate(3, ["insert a"]), false);
  expect(candidate(3, ["insert a", "insert b", "insert c"]), true);
  expect(candidate(3, ["insert a", "delete a"]), true);
  expect(candidate(3, ["insert a", "delete a", "undo"]), false);
  expect(candidate(2, ["insert a", "insert b", "undo", "insert c"]), false);
  expect(candidate(3, ["delete a"]), true);
  expect(candidate(3, ["insert a", "insert a"]), false);
