Map<String, int> countWifiSignalBins(int userX, int userY, List<List<int>> accessPoints) {
  final bins = {
    'excellent': 0,
    'good': 0,
    'fair': 0,
    'poor': 0,
    'unreachable': 0
  };
  for (final ap in accessPoints) {
    final dist = (userX - ap[0]).abs() + (userY - ap[1]).abs();
    if (dist <= 1) {
      bins['excellent'] = bins['excellent']! + 1;
    } else if (dist <= 3) {
      bins['good'] = bins['good']! + 1;
    } else if (dist <= 6) {
      bins['fair'] = bins['fair']! + 1;
    } else if (dist <= 10) {
      bins['poor'] = bins['poor']! + 1;
    } else {
      bins['unreachable'] = bins['unreachable']! + 1;
    }
  }
  return bins;
}

