@pragma('vm:entry-point')
double calculatePlaylistEncodingEfficiency(String playlist) {
  if (playlist.isEmpty) return 0.0;
  int originalLength = playlist.length;
  int encodedLength = 0;

  int vlqBytes(int value) {
    int bytes = 0;
    do {
      bytes++;
      value >>= 7;
    } while (value > 0);
    return bytes;
  }

  int i = 0;
  while (i < originalLength) {
    int runStart = i;
    String current = playlist[i];
    while (i < originalLength && playlist[i] == current) {
      i++;
    }
    int runLength = i - runStart;
    encodedLength += 1 + vlqBytes(runLength);
  }
  return originalLength / encodedLength;
}

@pragma('vm:entry-point')
void main() {
  assert(calculatePlaylistEncodingEfficiency("") == 0.0);
  assert(calculatePlaylistEncodingEfficiency("A") == 0.5);
  assert(calculatePlaylistEncodingEfficiency("AA") == 1.0);
  print('All tests passed!');
}

