@pragma('vm:entry-point')
String shelfStatus(List<int> bookCodes, int mask) {
  if (bookCodes.isEmpty) return "EMPTY";

  int popcount(int x) {
    int c = 0;
    while (x != 0) {
      c++;
      x &= x - 1;
    }
    return c;
  }

  int rotl16(int x, int shift) {
    shift %= 16;
    if (shift == 0) return x & 0xFFFF;
    return ((x << shift) | (x >> (16 - shift))) & 0xFFFF;
  }

  int combined = 0;
  int common = 0xFFFFFFFF;
  for (int code in bookCodes) {
    combined |= code;
    common &= code;
  }

  int specialCount = 0;
  for (int code in bookCodes) {
    if ((code & mask) != 0) specialCount++;
  }

  int combinedPop = popcount(combined);
  int commonPop = popcount(common);

  int value = (combined ^ (specialCount << 4)) |
              (commonPop << 8) |
              (combinedPop << 12);
  int rotated = rotl16(value & 0xFFFF, specialCount % 8);

  String binary = rotated.toRadixString(2).padLeft(16, '0');
  return "SHELF:$binary";
}

@pragma('vm:entry-point')
void main() {
  assert(shelfStatus([], 0) == "EMPTY");
  assert(shelfStatus([10], 0) == "SHELF:0010001000001010");
  assert(shelfStatus([10, 12], 8) == "SHELF:1100010100111011");
  print('All tests passed!');
}

