@pragma('vm:entry-point')
Map<String, int> longestIncreasingShelfPaths(List<List<String>> grid) {
  if (grid.isEmpty) return {};
  int rows = grid.length;
  List<List<int>> memo = List.generate(rows, (i) => List.filled(grid[i].length, 0));
  List<List<String>> categories = List.generate(rows, (i) => List.filled(grid[i].length, ''));
  List<List<int>> numbers = List.generate(rows, (i) => List.filled(grid[i].length, 0));

  for (int i = 0; i < rows; i++) {
    for (int j = 0; j < grid[i].length; j++) {
      String code = grid[i][j];
      categories[i][j] = code[0];
      numbers[i][j] = int.parse(code.substring(1));
    }
  }

  const List<List<int>> dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];

  int dfs(int r, int c) {
    if (memo[r][c] != 0) return memo[r][c];
    int maxLen = 1;
    String cat = categories[r][c];
    int num = numbers[r][c];
    for (var dir in dirs) {
      int nr = r + dir[0];
      int nc = c + dir[1];
      if (nr >= 0 && nr < rows && nc >= 0 && nc < grid[nr].length) {
        if (categories[nr][nc] == cat && numbers[nr][nc] > num) {
          int len = 1 + dfs(nr, nc);
          if (len > maxLen) maxLen = len;
        }
      }
    }
    memo[r][c] = maxLen;
    return maxLen;
  }

  Map<String, int> result = {};
  for (int i = 0; i < rows; i++) {
    for (int j = 0; j < grid[i].length; j++) {
      String cat = categories[i][j];
      int len = dfs(i, j);
      if (!result.containsKey(cat) || len > result[cat]!) {
        result[cat] = len;
      }
    }
  }
  return result;
}

@pragma('vm:entry-point')
void main() {
  assert(longestIncreasingShelfPaths([]).toString() == {}.toString());
  assert(longestIncreasingShelfPaths([['A1']]).toString() == {'A': 1}.toString());
  assert(longestIncreasingShelfPaths([['A1','A2'],['A3','A4']]).toString() == {'A': 3}.toString());
  print('All tests passed!');
}

tests:
void main() {
  final candidate = longestIncreasingShelfPaths;

  expect(candidate([]), {});
  expect(candidate([['A1']]), {'A': 1});
  expect(candidate([['A1', 'A2', 'A3']]), {'A': 3});
  expect(candidate([['A1'], ['A2'], ['A3']]), {'A': 3});
  expect(candidate([['A1', 'B1'], ['A2', 'B2']]), {'A': 2, 'B': 2});
  expect(candidate([['A1', 'A2', 'B1'], ['A3', 'A4', 'B2'], ['A5', 'A6', 'B3']]), {'A': 4, 'B': 3});
  expect(candidate([['A1', 'B1', 'A10'], ['B2', 'A2', 'B3'], ['A3', 'B4', 'A4']]), {'A': 1, 'B': 1});
  expect(candidate([['A1', 'A2', 'A3'], ['A6', 'A5', 'A4'], ['A7', 'A8', 'A9']]), {'A': 9});
