@pragma('vm:entry-point')
String soilMoistureScheduleLeadTime(int gridId, int sensorDayIndex, int currentDayIndex, int scheduledReadLag, List<int> recentMoistureValues) {
  if (recentMoistureValues.isEmpty) {
    return 'GRID_${gridId}_ERR_NO_DATA';
  }
  if (scheduledReadLag < 0) {
    return 'GRID_${gridId}_ERR_BAD_LAG';
  }
  int rawAge = currentDayIndex - sensorDayIndex;
  if (rawAge < 0) {
    return 'GRID_${gridId}_ERR_FUTURE';
  }
  int moistureSum = 0;
  int validPoints = 0;
  for (int val in recentMoistureValues) {
    if (val >= 0 && val <= 100) {
      moistureSum += val;
      validPoints++;
    }
  }
  if (validPoints == 0) {
    return 'GRID_${gridId}_ERR_INVALID_RANGE';
  }
  int avgMoisture = moistureSum ~/ validPoints;
  int adjustment = 0;
  if (avgMoisture < 20) {
    adjustment = -3;
  } else if (avgMoisture > 80) {
    adjustment = 2;
  } else if (avgMoisture >= 45 && avgMoisture <= 55) {
    adjustment = -1;
  }
  int leadTime = rawAge + scheduledReadLag + adjustment;
  if (leadTime < 0) {
    leadTime = 0;
  }
  return 'GRID_${gridId}_AGE_${rawAge}_LEAD_${leadTime}';
}

@pragma('vm:entry-point')
void main() {
  assert(soilMoistureScheduleLeadTime(17, 100, 105, 2, [30, 40, 50]) == 'GRID_17_AGE_5_LEAD_6');
  assert(soilMoistureScheduleLeadTime(3, 200, 195, 1, [90, 95]) == 'GRID_3_ERR_FUTURE');
  assert(soilMoistureScheduleLeadTime(8, 50, 60, -1, [10, 15]) == 'GRID_8_ERR_BAD_LAG');
  print('All tests passed!');
}

