String countSquaresByColor(List<String> squares) {
  Map<String, int> counts = {'dark': 0, 'light': 0};
  for (var sq in squares) {
    int file = sq.codeUnitAt(0) - 96;
    int rank = int.parse(sq[1]);
    String color = (file + rank).isEven ? 'dark' : 'light';
    counts[color] = counts[color]! + 1;
  }
  return 'dark:${counts['dark']}, light:${counts['light']}';
}

