@pragma('vm:entry-point')
Set<int> findDominantCandidates(List<Map<int, int>> precinctVotes, int windowSize) {
  if (precinctVotes.isEmpty || windowSize <= 0 || windowSize > precinctVotes.length) {
    return <int>{};
  }

  int? _majority(Map<int, int> freq) {
    int total = 0;
    freq.forEach((_, v) => total += v);
    for (final MapEntry<int, int> entry in freq.entries) {
      if (entry.value * 2 > total) return entry.key;
    }
    return null;
  }

  Map<int, int> freq = {};
  for (int i = 0; i < windowSize; i++) {
    precinctVotes[i].forEach((candidate, count) {
      freq[candidate] = (freq[candidate] ?? 0) + count;
    });
  }

  Set<int> result = {};
  int? winner = _majority(freq);
  if (winner != null) result.add(winner);

  for (int i = 0; i + windowSize < precinctVotes.length; i++) {
    precinctVotes[i].forEach((candidate, count) {
      int newVal = (freq[candidate] ?? 0) - count;
      if (newVal <= 0) {
        freq.remove(candidate);
      } else {
        freq[candidate] = newVal;
      }
    });
    precinctVotes[i + windowSize].forEach((candidate, count) {
      freq[candidate] = (freq[candidate] ?? 0) + count;
    });
    winner = _majority(freq);
    if (winner != null) result.add(winner);
  }
  return result;
}

