@pragma('vm:entry-point')
bool qrCodeRowHasKBlackModules(List<int> blackIndices, int size, int k) {
  if (size <= 0) return false;
  if (blackIndices.isEmpty) {
    return k == 0;
  }
  int lowerBound(List<int> list, int target, int from) {
    int left = from;
    int right = list.length - 1;
    int result = list.length;
    while (left <= right) {
      int mid = left + ((right - left) >> 1);
      if (list[mid] >= target) {
        result = mid;
        right = mid - 1;
      } else {
        left = mid + 1;
      }
    }
    return result;
  }
  int i = 0;
  int distinctRows = 0;
  while (i < blackIndices.length) {
    int row = blackIndices[i] ~/ size;
    distinctRows++;
    int end = lowerBound(blackIndices, (row + 1) * size, i);
    int count = end - i;
    if (count == k) return true;
    i = end;
  }
  if (k == 0 && distinctRows < size) return true;
  return false;
}

@pragma('vm:entry-point')
void main() {
  assert(qrCodeRowHasKBlackModules([], 5, 0) == true);
  assert(qrCodeRowHasKBlackModules([0, 1, 3, 4], 3, 1) == false);
  assert(qrCodeRowHasKBlackModules([0, 1, 2], 3, 3) == true);
  print('All tests passed!');
