@pragma('vm:entry-point')
List<int> mergeSameItemStacks(List<List<int>> inventory, int capacity) {
  if (inventory.isEmpty) return [];

  // Map from item ID to total count
  Map<int, int> totals = {};
  for (var stack in inventory) {
    int id = stack[0];
    int count = stack[1];
    totals[id] = (totals[id] ?? 0) + count;
  }

  // Split into full stacks and remainder, preserving insertion order of IDs
  List<int> result = [];
  Set<int> seen = {};
  for (var stack in inventory) {
    int id = stack[0];
    if (seen.contains(id)) continue;
    seen.add(id);

    int total = totals[id]!;
    int fullStacks = total ~/ capacity;
    int remainder = total % capacity;

    for (int i = 0; i < fullStacks; i++) {
      result.add(capacity);
    }
    if (remainder > 0) {
      result.add(remainder);
    }
  }

  return result;
}

@pragma('vm:entry-point')
