  assert(mergeSameItemStacks([[1, 3], [1, 4], [2, 5]], 4).toString() == '[4, 3, 4, 1]');
  assert(mergeSameItemStacks([], 5).toString() == '[]');
  assert(mergeSameItemStacks([[7, 2]], 5).toString() == '[2]');
