@pragma('vm:entry-point')
double averageSpiralPickDistance(List<List<int>> inventory, int targetItems) {
  if (inventory.isEmpty) return 0.0;
  int rows = inventory.length;
  int cols = inventory[0].length;
  if (cols == 0) return 0.0;
  if (targetItems <= 0) return 0.0;

  int remaining = targetItems;
  int distanceSum = 0;
  int totalPicked = 0;

  int top = 0, bottom = rows - 1;
  int left = 0, right = cols - 1;

  outerLoop:
  while (top <= bottom && left <= right) {
    for (int col = left; col <= right; col++) {
      if (remaining <= 0) break outerLoop;
      int qty = inventory[top][col];
      if (qty < 0) qty = 0;
      int take = (qty < remaining) ? qty : remaining;
      if (take > 0) {
        int dist = top + col;
        distanceSum += dist * take;
        totalPicked += take;
        remaining -= take;
      }
    }
    top++;

    for (int row = top; row <= bottom; row++) {
      if (remaining <= 0) break outerLoop;
      int qty = inventory[row][right];
      if (qty < 0) qty = 0;
      int take = (qty < remaining) ? qty : remaining;
      if (take > 0) {
        int dist = row + right;
        distanceSum += dist * take;
        totalPicked += take;
        remaining -= take;
      }
    }
    right--;

    if (top <= bottom) {
      for (int col = right; col >= left; col--) {
        if (remaining <= 0) break outerLoop;
        int qty = inventory[bottom][col];
        if (qty < 0) qty = 0;
        int take = (qty < remaining) ? qty : remaining;
        if (take > 0) {
          int dist = bottom + col;
          distanceSum += dist * take;
          totalPicked += take;
          remaining -= take;
        }
      }
      bottom--;
    }

    if (left <= right) {
      for (int row = bottom; row >= top; row--) {
        if (remaining <= 0) break outerLoop;
        int qty = inventory[row][left];
        if (qty < 0) qty = 0;
        int take = (qty < remaining) ? qty : remaining;
        if (take > 0) {
          int dist = row + left;
          distanceSum += dist * take;
          totalPicked += take;
          remaining -= take;
        }
      }
      left++;
    }
  }

  if (totalPicked == 0) return 0.0;
  return distanceSum / totalPicked;
}

