List<int> scaleRecipe(List<Object> recipe, double multiplier) {
  List<int> result = [];
  for (var item in recipe) {
    if (item is int) {
      result.add((item * multiplier).round());
    } else {
      var subInfo = item as List<Object>;
      double subMult = subInfo[0] as double;
      List<Object> subRec = subInfo[1] as List<Object>;
      result.addAll(scaleRecipe(subRec, multiplier * subMult));
    }
  }
  return result;
}

