bool diceGameEndsOnWeekend(int startDay, List<int> diceRolls) {
  int currentDay = startDay;
  for (int roll in diceRolls) {
    if (roll == 1) {
      currentDay += 2;
    } else if (roll == 6) {
      currentDay += 5;
    } else {
      currentDay += roll;
