@pragma('vm:entry-point')
String nextTrainAfter(int schedule, int minute, int delayMinutes) {
  const int MASK60 = (1 << 60) - 1;
  final int rotated = delayMinutes == 0
      ? schedule & MASK60
      : ((schedule << delayMinutes) | (schedule >> (60 - delayMinutes))) & MASK60;

  if (rotated == 0) {
    return "No trains";
  }

  int trailingZeros(int x) {
    int count = 0;
    while ((x & 1) == 0) {
      x >>= 1;
      count++;
    }
    return count;
  }

  final int higherMask = MASK60 ^ ((1 << (minute + 1)) - 1);
  final int afterBits = rotated & higherMask;
  if (afterBits != 0) {
    return "Next train at minute ${trailingZeros(afterBits)}";
  }

  final int lowerMask = (1 << (minute + 1)) - 1;
  final int lowerBits = rotated & lowerMask;
  // rotated is non‑zero, so lowerBits is non‑zero because all bits are covered
  return "Next train at minute ${trailingZeros(lowerBits)}";
}

@pragma('vm:entry-point')
void main() {
  assert(nextTrainAfter((1 << 5) | (1 << 10), 6, 2) == "Next train at minute 7");
  assert(nextTrainAfter(0, 10, 0) == "No trains");
  assert(nextTrainAfter(1 << 59, 58, 0) == "Next train at minute 59");
  print('All tests passed!');
}

