  expect(candidate(1 << 5, 5, 0), "Next train at minute 5");
  expect(candidate(1 << 10, 10, 3), "Next train at minute 13");
  expect(candidate(1 << 59, 0, 1), "Next train at minute 0");
  expect(candidate(1 << 59, 59, 1), "Next train at minute 0");
  expect(candidate((1 << 60) - 1, 30, 0), "Next train at minute 31");
  expect(candidate((1 << 60) - 1, 59, 0), "Next train at minute 0");
}

