List<String> runLengthEncodeQrRow(String row) {
  if (row.isEmpty) return [];
  List<String> result = [];
  int count = 1;
  for (int i = 1; i < row.length; i++) {
    if (row[i] == row[i - 1]) {
      count++;
    } else {
      result.add('$count${row[i - 1]}');
      count = 1;
    }
  }
  result.add('$count${row[row.length - 1]}');
  return result;
}

