  assert(optimalChargeCycleCount([[20, 50, 30, 45], [10, 60, 55]], 100)['cycles'] == 2);
  assert(optimalChargeCycleCount([[10, 20, 15], [30, 40, 35], [50, 60, 55]], 100)['depth'] == 10);
