@pragma('vm:entry-point')
List<String> generatePassSchedule(List<String> satellites, int passesPerSatellite) {
  if (passesPerSatellite <= 0 || satellites.isEmpty) return [];
  var queue = <MapEntry<String, int>>[];
  for (var sat in satellites) {
    queue.add(MapEntry(sat, passesPerSatellite));
  }
  List<String> schedule = [];
  while (queue.isNotEmpty) {
    var entry = queue.removeAt(0);
    schedule.add('${entry.key} pass ${passesPerSatellite - entry.value + 1}');
    if (entry.value > 1) {
      queue.add(MapEntry(entry.key, entry.value - 1));
    }
  }
  return schedule;
}

