  assert(longestConstantRoundedSegment([])["length"] == 0);
  assert(longestConstantRoundedSegment([199, 198, 195])["length"] == 2);
  assert(longestConstantRoundedSegment([5])["startIndex"] == 0);
  print('All tests passed!');
}

