@pragma('vm:entry-point')
List<int> simulateBatteryUndoLog(List<int> cycleDeltas) {
  final history = <int>[];
  final levels = <int>[];
  var level = 0;
  for (final d in cycleDeltas) {
    if (d == 0) {
      if (history.isNotEmpty) {
        level = history.removeLast();
      }
    } else {
      history.add(level);
      level += d;
    }
    levels.add(level);
  }
  return levels;
}

@pragma('vm:entry-point')
void main() {
  assert(simulateBatteryUndoLog([10, 20, 0]).toString() == '[10, 30, 10]');
  assert(simulateBatteryUndoLog([0, 0, 5]).toString() == '[0, 0, 5]');
  assert(simulateBatteryUndoLog([]).isEmpty);
