Map<String, int> spellCheckerEditGcd(String draft, String correct) {
  int gcd(int a, int b) { while (b != 0) { final t = a % b; a = b; b = t; } return a; }
  final positions = <int>[];
  final n = draft.length > correct.length ? draft.length : correct.length;
  for (var i = 0; i < n; i++) {
    if ((i < draft.length ? draft[i] : '') != (i < correct.length ? correct[i] : '')) {
      positions.add(i + 1);
    }
  }
  var g = 0;
  for (final p in positions) g = gcd(g, p);
  return {'editGcd': g, 'mismatchCount': positions.length};
}

