  final candidate = nextDepartureDensity;

  expect(candidate(0, 10), 'No service');
  expect(candidate(0, -1), 'Invalid');
  expect(candidate((1 << 10) | (1 << 40), 5), 'Next at 10, Density: low');
  expect(candidate((1 << 5) | (1 << 15), 20), 'Next at 5 (next hour), Density: low');
  expect(candidate((1 << 10) | (1 << 12) | (1 << 14) | (1 << 16) | (1 << 18), 5), 'Next at 10, Density: high');
  expect(candidate((1 << 20) | (1 << 25) | (1 << 30), 15), 'Next at 20, Density: medium');
  expect(candidate((1 << 59), 30), 'Next at 59, Density: low');
  expect(candidate((1 << 0) | (1 << 1), 59), 'Next at 0 (next hour), Density: low');
}

