String rgbPixelsToHexCsv(List<int> pixels) {
  final parts = <String>[];
  for (final pixel in pixels) {
    final r = (pixel >> 16) & 0xFF;
    final g = (pixel >> 8) & 0xFF;
    final b = pixel & 0xFF;
    parts.add(
