int totalTournamentPoints(List<int> ratings) {
  if (ratings.length <= 1) return 0;
  int points = 0;
  List<int> winners = [];
  for (int i = 0; i < ratings.length; i += 2) {
    points += ratings[i] + ratings[i + 1];
    if (ratings[i] >= ratings[i + 1]) {
      winners.add(ratings[i]);
    } else {
      winners.add(ratings[i + 1]);
    }
  }
  return points + totalTournamentPoints(winners);
}

