@pragma('vm:entry-point')
String championPath(List<int> strengths) {
  int n = strengths.length;
  if (n == 1) return '';
  List<int> winners = List<int>.from(strengths);
  List<List<int>> history = List<List<int>>.generate(n, (_) => <int>[]);
  while (winners.length > 1) {
    List<int> nextWinners = <int>[];
    List<List<int>> nextHistory = <List<int>>[];
    for (int i = 0; i < winners.length; i += 2) {
      if (winners[i] >= winners[i + 1]) {
        nextWinners.add(winners[i]);
        nextHistory.add(<int>[...history[i], winners[i + 1]]);
      } else {
        nextWinners.add(winners[i + 1]);
        nextHistory.add(<int>[...history[i + 1], winners[i]]);
      }
    }
    winners = nextWinners;
    history = nextHistory;
  }
  return history[0].join(',');
}

