String findMinimumPacket(List<int> sizes, int requested) {
  int low = 0;
  int high = sizes.length - 1;
  int result = -1;
  while (low <= high) {
    int mid = low + (high - low) ~/ 2;
    if (sizes[mid] >= requested) {
      result = sizes[mid];
      high = mid - 1;
    } else {
      low = mid + 1;
    }
  }
  return result == -1 ? 'FRAGMENT' : result.toString();
}

