  final candidate = longestStableCodonRun;

  expect(candidate("ATGCCGAAA"), 1);
  expect(candidate("GCCGCCGCC"), 3);
  expect(candidate(""), 0);
  expect(candidate("AT"), 0);
  expect(candidate("GCG"), 1);
  expect(candidate("ATGATGATG"), 0);
  expect(candidate("CCGATGCCG"), 1);
