@pragma('vm:entry-point')
Map<String, int> analyzeChargeCycles(List<List<int>> cycles) {
  if (cycles.isEmpty) {
    return {'activeDays': 0, 'peakOverlap': 0, 'longestRest': 0, 'fragmentation': 0};
  }
  Map<int, int> events = {};
  for (var c in cycles) {
    events[c[0]] = (events[c[0]] ?? 0) + 1;
    events[c[1] + 1] = (events[c[1] + 1] ?? 0) - 1;
  }
  List<int> days = events.keys.toList()..sort();
  int peakOverlap = 0;
  int cur = 0;
  for (var d in days) {
    cur += events[d]!;
    if (cur > peakOverlap) peakOverlap = cur;
  }
  List<List<int>> sorted = List.from(cycles);
  sorted.sort((a, b) => a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]);
  List<List<int>> merged = [List.from(sorted[0])];
  for (int i = 1; i < sorted.length; i++) {
    var last = merged.last;
    if (sorted[i][0] <= last[1] + 1) {
      if (sorted[i][1] > last[1]) last[1] = sorted[i][1];
    } else {
      merged.add(List.from(sorted[i]));
    }
  }
  int activeDays = 0;
  for (var m in merged) {
    activeDays += m[1] - m[0] + 1;
  }
  int longestRest = 0;
  for (int i = 1; i < merged.length; i++) {
    int gap = merged[i][0] - merged[i - 1][1] - 1;
    if (gap > longestRest) longestRest = gap;
  }
  return {
    'activeDays': activeDays,
    'peakOverlap': peakOverlap,
    'longestRest': longestRest,
    'fragmentation': merged.length,
  };
}

@pragma('vm:entry-point')
void main() {
  assert(analyzeChargeCycles([[1, 3], [5, 7]])['activeDays'] == 6);
  assert(analyzeChargeCycles([[1, 5], [3, 8]])['peakOverlap'] == 2);
  assert(analyzeChargeCycles([])['fragmentation'] == 0);
  print('All tests passed!');
}

