String barcodeOverlapCheck(List<List<int>> regions) {
  int totalOverlap = 0;
  for (int i = 0; i < regions.length; i++) {
    for (int j = i + 1; j < regions.length; j++) {
      int x1 = regions[i][0], y1 = regions[i][1], x2 = regions[i][2], y2 = regions[i][3];
      int x3 = regions[j][0], y3 = regions[j][1], x4 = regions[j][2], y4 = regions[j][3];
      int overlapX = (x2 < x4 ? x2 : x4) - (x1 > x3 ? x1 : x3);
      int overlapY = (y2 < y4 ? y2 : y4) - (y1 > y3 ? y1 : y3);
      if (overlapX > 0 && overlapY > 0) {
        totalOverlap += overlapX * overlapY;
      }
    }
  }
  return totalOverlap == 0 ? "VALID" : totalOverlap.toString();
}

