@pragma('vm:entry-point')
Set<int> findPlaylistSizes(List<int> songDurations, int targetMinutes) {
  Set<int> validSizes = {};

  void backtrack(int index, int currentSum, int currentCount, int lastPicked) {
    if (currentSum == targetMinutes) {
      validSizes.add(currentCount);
      return;
    }
    if (currentSum > targetMinutes || index >= songDurations.length) {
      return;
    }

    // Option 1: Skip this song
    backtrack(index + 1, currentSum, currentCount, lastPicked);

    // Option 2: Take this song only if not adjacent to last picked song
    if (lastPicked != index - 1) {
      backtrack(
        index + 1,
        currentSum + songDurations[index],
        currentCount + 1,
        index,
      );
    }
  }

  backtrack(0, 0, 0, -2);
  return validSizes;
}

@pragma('vm:entry-point')
void main() {
  assert(findPlaylistSizes([3, 2, 4, 1, 5], 7).contains(2));
  assert(findPlaylistSizes([2, 1, 2, 1, 2, 1], 4).length == 2);
  assert(findPlaylistSizes([], 0).contains(0));
