  expect(processSeatingChart({'A': 5}, ['RESERVE:A:10', 'UNDO'])['A'], 5);
  expect(processSeatingChart({'A': 10}, ['RESERVE:A:3', 'RELEASE:A:2', 'UNDO'])['A'], 10);
  expect(processSeatingChart({'A': 10, 'B': 5}, ['RESERVE:A:2', 'RESERVE:B:1', 'RESERVE:A:3', 'UNDO', 'UNDO'])['A'], 8);
