@pragma('vm:entry-point')
String sortBarcodesByCheckDigit(List<String> barcodes) {
  var sorted = List<String>.from(barcodes);
  sorted.sort((a, b) {
    int checkA = int.parse(a[a.length - 1]);
    int checkB = int.parse(b[b.length - 1]);
    if (checkA != checkB) return checkA.compareTo(checkB);
    if (a.length != b.length) return a.length.compareTo(b.length);
    return a.compareTo(b);
  });
  return sorted.join(',');
}

