@pragma('vm:entry-point')
List<String> diceRoundTerritoryAnalysis(List<List<List<int>>> playerMoves) {
  int n = playerMoves.length;
  List<List<int>> aabbs = [];
  Set<int> xCoords = {};
  Set<int> yCoords = {};

  for (var moves in playerMoves) {
    int x = 0, y = 0;
    int minX = 0, minY = 0, maxX = 0, maxY = 0;
    for (var move in moves) {
      x += move[0];
      y += move[1];
      minX = minX < x ? minX : x;
      maxX = maxX > x ? maxX : x;
      minY = minY < y ? minY : y;
      maxY = maxY > y ? maxY : y;
    }
    aabbs.add([minX, minY, maxX, maxY]);
    xCoords.addAll([minX, maxX]);
    yCoords.addAll([minY, maxY]);
  }

  List<int> xs = xCoords.toList()..sort();
  List<int> ys = yCoords.toList()..sort();

  int unionArea = 0;
  List<List<int>> pairOverlap = List.generate(n, (_) => List.filled(n, 0));

  for (int i = 0; i < xs.length - 1; i++) {
    for (int j = 0; j < ys.length - 1; j++) {
      int cellArea = (xs[i + 1] - xs[i]) * (ys[j + 1] - ys[j]);
      List<int> covering = [];
      for (int p = 0; p < n; p++) {
        if (aabbs[p][0] <= xs[i] && aabbs[p][1] <= ys[j] &&
            aabbs[p][2] >= xs[i + 1] && aabbs[p][3] >= ys[j + 1]) {
          covering.add(p);
        }
      }
      if (covering.isNotEmpty) {
        unionArea += cellArea;
        for (int a = 0; a < covering.length; a++) {
          for (int b = a + 1; b < covering.length; b++) {
            pairOverlap[covering[a]][covering[b]] += cellArea;
          }
        }
      }
    }
  }

  List<String> result = ['union:$unionArea'];
  for (int i = 0; i < n; i++) {
    for (int j = i + 1; j < n; j++) {
      if (pairOverlap[i][j] > 0) {
        result.add('$i-$j:${pairOverlap[i][j]}');
      }
    }
  }
  return result;
}

