List<String> sortAsciiArtRows(List<String> rows) {
  List<String> result = List<String>.from(rows);
  result.sort((a, b) {
    int countA = 0;
    int firstA = a.length;
    for (int i = 0; i < a.length; i++) {
      if (a[i] != ' ') {
        countA++;
        if (firstA == a.length) firstA = i;
      }
    }
    int countB = 0;
    int firstB = b.length;
    for (int i = 0; i < b.length; i++) {
      if (b[i] != ' ') {
        countB++;
        if (firstB == b.length) firstB = i;
      }
    }
    if (countA != countB) {
      return countB.compareTo(countA);
    }
    if (firstA != firstB) {
      return firstA.compareTo(firstB);
    }
    return a.compareTo(b);
  });
  return result;
}

