  assert(classifyPixelDominance(["200,50,50", "210,60,40", "50,200,50", "100,100,100", "120,110,100"]).toString() == "[N, R]");
  assert(classifyPixelDominance([]).toString() == "[]");
  assert(classifyPixelDominance(["255,0,0", "0,255,0", "0,0,255", "255,0,0", "0,255,0", "0,0,255"]).toString() == "[B, G, R]");
  print('All tests passed!');
}

