List<String> maxLootNoTriple(List<int> itemValues) {
  int n = itemValues.length;
  if (n == 0) return [];
  List<int> dp = List<int>.filled(n, 0);
  dp[0] = itemValues[0];
  if (n > 1) dp[1] = itemValues[0] + itemValues[1];
  if (n > 2) {
    int a = dp[1], b = dp[0] + itemValues[2], c = itemValues[1] + itemValues[2];
    dp[2] = a > b ? (a > c ? a : c) : (b > c ? b : c);
  }
  for (int i = 3; i < n; i++) {
    int a = dp[i - 1], b = dp[i - 2] + itemValues[i], c = dp[i - 3] + itemValues[i] + itemValues[i - 1];
    dp[i] = a > b ? (a > c ? a : c) : (b > c ? b : c);
  }
  return dp.map((v) => v.toString()).toList();
}

