@pragma('vm:entry-point')
Set<int> findCorridorCells(List<int> energy, int budget, int minLength) {
  Set<int> result = {};
  if (energy.isEmpty || minLength > energy.length) {
    return result;
  }
  int left = 0;
  int sum = 0;
  int blockStart = -1;
  int blockEnd = -1;
  for (int right = 0; right < energy.length; right++) {
    sum += energy[right];
    while (sum > budget && left <= right) {
      sum -= energy[left];
      left++;
    }
    int windowLen = right - left + 1;
    if (left <= right && windowLen >= minLength) {
      if (blockEnd == -1 || left > blockEnd + 1) {
        blockStart = left;
        blockEnd = right;
        for (int i = left; i <= right; i++) {
          result.add(i);
        }
      } else {
        if (right > blockEnd) {
          for (int i = blockEnd + 1; i <= right; i++) {
            result.add(i);
          }
          blockEnd = right;
        }
      }
    }
  }
  return result;
}

