/// Recursively calculates the total scaled grams of ingredients
/// using a divide-and-conquer approach on sublists.
int calculateTotalScaledGrams(List<int> amounts, int scaleFactor) {
  if (amounts.isEmpty) return 0;
  if (amounts.length == 1) return amounts[0] * scaleFactor;

  int mid = amounts.length ~/ 2;
  return calculateTotalScaledGrams(amounts.sublist(0, mid), scaleFactor) +
         calculateTotalScaledGrams(amounts.sublist(mid), scaleFactor);
}

