@pragma('vm:entry-point')
int minBlackModulesForValidQrRow(List<int> modules) {
  if (modules.isEmpty) return 0;
  const int inf = 1000000000;
  List<List<int>> dp = [
    [inf, inf, inf],
    [inf, inf, inf],
  ];
  dp[0][1] = 0;
  dp[1][1] = 1;

  for (int i = 0; i < modules.length; i++) {
    List<List<int>> nextDp = [
      [inf, inf, inf],
      [inf, inf, inf],
    ];
    List<int> allowed = (modules[i] == 2) ? [0, 1] : [modules[i]];

    for (int c in allowed) {
      for (int prevC = 0; prevC <= 1; prevC++) {
        for (int prevLen = 1; prevLen <= 2; prevLen++) {
          if (dp[prevC][prevLen] == inf) continue;

          if (c == prevC) {
            if (prevLen == 1) {
              int cost = dp[prevC][1] + c;
              if (cost < nextDp[c][2]) nextDp[c][2] = cost;
            }
          } else {
            int cost = dp[prevC][prevLen] + c;
            if (cost < nextDp[c][1]) nextDp[c][1] = cost;
          }
        }
      }
    }
    dp = nextDp;
  }

  int minCost = inf;
  for (int c = 0; c <= 1; c++) {
    for (int len = 1; len <= 2; len++) {
      if (dp[c][len] < minCost) {
        minCost = dp[c][len];
      }
    }
  }

  return minCost == inf ? -1 : minCost;
}

