  assert(minBlackModulesForValidQrRow([2, 2, 2]) == 1);
  assert(minBlackModulesForValidQrRow([0, 0, 0]) == -1);
  assert(minBlackModulesForValidQrRow([1, 2, 0, 2, 1]) == 1);
  print('All tests passed!');
}

