bool isValidPokerDiceEncoding(String encoded) {
  if (encoded.isEmpty || encoded.length % 2 != 0) return false;
  int totalDice = 0;
  for (int i = 0; i < encoded.length; i += 2) {
    int? count = int.tryParse(encoded[i]);
    int? face = int.tryParse(encoded[i + 1]);
    if (count == null || face == null) return false;
    if (count < 1 || count > 5) return false;
    if (face < 1 || face > 6) return false;
    totalDice += count;
  }
  return totalDice == 5;
}

