  expect(parseRgbPixelStream('r300g10b10p'), {'pixels': 0, 'errors': 2, 'totalR': 0, 'totalG': 0, 'totalB': 0});
  expect(parseRgbPixelStream('r10g20b30cr40g50b60p'), {'pixels': 1, 'errors': 0, 'totalR': 40, 'totalG': 50, 'totalB': 60});
