List<String> findOptimalRgbPath(List<List<int>> grid, int maxDiff) {
  if (grid.isEmpty || grid[0].isEmpty) return [];
  int rows = grid.length, cols = grid[0].length;
  List<int> cost = List.filled(cols, 0), nextCol = List.filled(cols, -1);
  for (int r = rows - 2; r >= 0; r--) {
    List<int> newCost = List.filled(cols, 0x3FFFFFFF), newNext = List.filled(cols, -1);
    for (int c = 0; c < cols; c++) {
      int curr = grid[r][c];
      for (int nc = c - 1; nc <= c + 1; nc++) {
        if (nc >= 0 && nc < cols) {
          int nxt = grid[r + 1][nc];
          int dist = (((curr >> 16) & 0xFF) - ((nxt >> 16) & 0xFF)).abs() +
                     (((curr >> 8) & 0xFF) - ((nxt >> 8) & 0xFF)).abs() +
                     ((curr & 0xFF) - (nxt & 0xFF)).abs();
          if (dist <= maxDiff) {
            int total = dist + cost[nc];
            if (total < newCost[c] || (total == newCost[c] && (newNext[c] == -1 || nc < newNext[c]))) {
              newCost[c] = total;
              newNext[c] = nc;
            }
          }
        }
      }
    }
    cost = newCost;
    nextCol = newNext;
  }
  int minCost = 0x3FFFFFFF, bestStartC = -1;
  for (int c = 0; c < cols; c++) {
    if (cost[c] < minCost || (cost[c] == minCost && (bestStartC == -1 || c < bestStartC))) {
      minCost = cost[c];
      bestStartC = c;
    }
  }
  if (bestStartC == -1) return [];
  List<String> path = [];
  int currC = bestStartC;
  for (int r = 0; r < rows; r++) {
    path.add('#${grid[r][currC].toRadixString(16).padLeft(6, '0').toUpperCase()}');
    currC = nextCol[currC];
  }
  return path;
}

