void main() {
  assert(findOptimalRgbPath([[0xFF0000]], 10).toString() == '[#FF0000]');
  assert(findOptimalRgbPath([[0xFF0000], [0x00FF00]], 10).toString() == '[]');
  assert(findOptimalRgbPath([[0x000000, 0x000000], [0x000000, 0x000000]], 0).toString() == '[#000000, #000000]');
  print('All tests passed!');
}

