@pragma('vm:entry-point')
int calculateValidIncumbentVotes(List<List<int>> precinctVotes, int minThreshold) {
  int total = 0;
  for (var row in precinctVotes) {
    int rowSum = row.fold(0, (a, b) => a + b);
    if (rowSum > minThreshold) {
      total += row.where((v) => v == 1).length;
    }
  }
  return total;
}

