  assert(calculateValidIncumbentVotes([[1, 1, 0], [1, 0, 0], [1, 1, 1]], 1) == 5);
  assert(calculateValidIncumbentVotes([[0, 0], [1, 1]], 1) == 2);
  assert(calculateValidIncumbentVotes([], 0) == 0);
  print('All tests passed!');
}

