int calculateNetBalance(List<Map<String, int>> ledger) {
  final result = ledger.fold<Map<String, int>>(
    {'balance': 0, 'pendingAmount': 0, 'maxFee': 0},
    (acc, entry) {
      if (entry['isDeposit'] == 1) {
        int newBalance = acc['balance']! + entry['amount']!;
        if (acc['pendingAmount']! > 0) {
          newBalance -= (acc['pendingAmount']! + acc['maxFee']!);
        }
        return {'balance': newBalance, 'pendingAmount': 0, 'maxFee': 0};
      } else {
        int newPending = acc['pendingAmount']! + entry['amount']!;
        int fee = entry['fee'] ?? 0;
        int newMaxFee = fee > acc['maxFee']! ? fee : acc['maxFee']!;
        return {
          'balance': acc['balance']!,
          'pendingAmount': newPending,
          'maxFee': newMaxFee
        };
      }
    },
  );
  return result['balance']! - result['pendingAmount']! - result['maxFee']!;
}

