void main() {
  assert(isValidServerLogLine('[INFO] auth:User logged in') == true);
  assert(isValidServerLogLine('[ERROR] 123db:Fail') == false);
  assert(isValidServerLogLine('[WARN] a:b\n') == false);
  print('All tests passed!');
}

