bool isValidTideChecksum(String readings) {
  int dashIndex = readings.lastIndexOf('-');
  if (dashIndex <= 0 || dashIndex != readings.length - 2) return false;
  int? checksum = int.tryParse(readings[dashIndex + 1]);
  if (checksum == null) return false;
  int sum = 0;
  for (int i = 0; i < dashIndex; i++) {
    String c = readings[i];
    if (c == 'L') sum += 1;
    else if (c == 'M') sum += 2;
    else if (c == 'H') sum += 3;
    else return false;
  }
  return sum % 10 == checksum;
}

