double calculateMedianPacketSize(List<int> packetSizes) {
  if (packetSizes.isEmpty) {
    return 0.0;
  }
  List<int> sorted = List<int>.from(packetSizes);
  sorted.sort((int a, int b) => a.compareTo(b));
  int mid = sorted.length ~/ 2;
  if (sorted.length % 2 == 0) {
    return (sorted[mid] + sorted[mid - 1]) / 2.0;
  }
  return sorted[mid].toDouble();
}

