int findQrRowIndexWithMinBlackModules(List<int> blackCounts, int target) {
  int left = 0;
  int right = blackCounts.length - 1;
  int firstIndex = -1;
  while (left <= right) {
    int mid = left + ((right - left) >> 1);
    if (blackCounts[mid] >= target) {
      firstIndex = mid;
      right = mid - 1;
    } else {
      left = mid + 1;
    }
  }
  return firstIndex;
}

@pragma('vm:entry-point')
