List<String> sortRgbByGreenProximity(List<String> colors) {
  List<String> result = List<String>.from(colors);
  result.sort((String a, String b) {
    List<String> pa = a.split(',');
    List<String> pb = b.split(',');
    int ra = int.parse(pa[0]), ga = int.parse(pa[1]), ba = int.parse(pa[2]);
    int rb = int.parse(pb[0]), gb = int.parse(pb[1]), bb = int.parse(pb[2]);
    int da = ra * ra + (ga - 255) * (ga - 255) + ba * ba;
    int db = rb * rb + (gb - 255) * (gb - 255) + bb * bb;
    if (da != db) return da.compareTo(db);
    if (ra != rb) return ra.compareTo(rb);
    if (ga != gb) return ga.compareTo(gb);
    return ba.compareTo(bb);
  });
  return result;
}

