double computeLuminanceVariance(List<List<List<int>>> pixels) {
  if (pixels.isEmpty) return 0.0;
  int rows = pixels.length;
  int cols = pixels[0].length;
  if (cols == 0) return 0.0;

  int count = 0;
  double sum = 0.0;

  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      var px = pixels[r][c];
      double lum = 0.25 * px[0] + 0.5 * px[1] + 0.25 * px[2];
      sum += lum;
      count++;
    }
  }

  if (count == 0) return 0.0;
  double mean = sum / count;

  double sqDiffSum = 0.0;
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      var px = pixels[r][c];
      double lum = 0.25 * px[0] + 0.5 * px[1] + 0.25 * px[2];
      sqDiffSum += (lum - mean) * (lum - mean);
    }
  }

  return sqDiffSum / count;
}

