@pragma('vm:entry-point')
List<int> manifestContainerSizes(List<int> quantities, int minSize) {
  if (quantities.isEmpty || minSize < 1) {
    return [];
  }

  // Collect non-zero quantities; zero-quantity items impose no constraint
  List<int> nonZero = [];
  for (int q in quantities) {
    if (q > 0) {
      nonZero.add(q);
    }
  }
  if (nonZero.isEmpty) {
    return [];
  }

  // Euclidean algorithm: compute GCD of all non-zero quantities
  int g = nonZero[0];
  for (int i = 1; i < nonZero.length; i++) {
    int a = g;
    int b = nonZero[i];
    while (b != 0) {
      int temp = b;
      b = a % b;
      a = temp;
    }
    g = a;
  }

  // Enumerate divisors of g that are >= minSize
  List<int> divisors = [];
  int i = 1;
  while (i * i <= g) {
    if (g % i == 0) {
      if (i >= minSize) {
        divisors.add(i);
      }
      int complement = g ~/ i;
      if (complement != i && complement >= minSize) {
        divisors.add(complement);
      }
    }
    i++;
  }

  divisors.sort();
  return divisors;
}

