@pragma('vm:entry-point')
List<String> hashBucketSignatures(List<String> keys, int bucketCount) {
  Set<int> occupied = {};
  for (String key in keys) {
    int hash = 0;
    for (int i = 0; i < key.length; i++) {
      hash += key.codeUnitAt(i);
    }
    occupied.add(hash % bucketCount);
  }

  List<String> recurse(int lo, int hi) {
    int rangeSize = hi - lo;
    if (rangeSize <= 0) return [];
    if (rangeSize == 1) {
      return occupied.contains(lo) ? ['B:$lo'] : [];
    }
    int mid = lo + (rangeSize ~/ 2);
    List<String> left = recurse(lo, mid);
    List<String> right = recurse(mid, hi);
    if (left.isNotEmpty && right.isNotEmpty) {
      return ['G:$rangeSize', ...left, ...right];
    } else if (left.isNotEmpty) {
      return left;
    } else {
      return right;
    }
  }

  return recurse(0, bucketCount);
}

@pragma('vm:entry-point')
