@pragma('vm:entry-point')
int bestStraightScore(List<int> hand) {
  if (hand.isEmpty) return 0;

  // Deduplicate and sort card values
  List<int> unique = hand.toSet().toList()..sort();

  // Find all consecutive runs
  List<List<int>> runs = [];
  List<int> currentRun = [unique[0]];

  for (int i = 1; i < unique.length; i++) {
    if (unique[i] == unique[i - 1] + 1) {
      currentRun.add(unique[i]);
    } else {
      runs.add(currentRun);
      currentRun = [unique[i]];
    }
  }
  runs.add(currentRun);

  // Find maximum run length
  int maxLen = 0;
  for (var run in runs) {
    if (run.length > maxLen) maxLen = run.length;
  }

  // Among runs of max length, pick the one with highest sum
  int bestSum = 0;
  for (var run in runs) {
    if (run.length == maxLen) {
      int sum = run.fold(0, (a, b) => a + b);
      if (sum > bestSum) bestSum = sum;
    }
  }

  return bestSum * maxLen;
}

