Set<int> satellitePassMinutes(int gx, int gy, int sx, int sy, int dx, int dy, int maxT, int r) {
  Set<int> result = {};
  for (int t = 0; t <= maxT; t++) {
    int satX = sx + t * dx;
    int satY = sy + t * dy;
    int dist = (satX - gx).abs() + (satY - gy).abs();
    if (dist <= r) {
      result.add(t);
    }
  }
  return result;
}

