bool scaledRecipeOverlaps(List<int> recipe, List<int> ingredient, int scale) {
  if (scale < 1) return false;
  int scaledW = recipe[2] * scale;
  int scaledH = recipe[3] * scale;
  return recipe[0] < ingredient[0] + ingredient[2] &&
         recipe[0] + scaledW > ingredient[0] &&
