@pragma('vm:entry-point')
String computeLocationNetTransfer(String log, String sku, String location) {
  if (log.isEmpty) {
    return "LOC:$location|SKU:$sku|NET:+0";
  }

  int netQty = 0;
  List<String> records = log.split(';');

  for (String record in records) {
    if (record.trim().isEmpty) continue;

    Map<String, String> fields = {};
    List<String> parts = record.split('|');
    for (String part in parts) {
      List<String> kv = part.split(':');
      if (kv.length >= 2) {
        fields[kv[0].trim()] = kv.sublist(1).join(':').trim();
      }
    }

    if (fields['SKU'] != sku) continue;

    int qty = int.tryParse(fields['QTY'] ?? '0') ?? 0;

    if (fields['FROM'] == location) {
      netQty -= qty;
    }
    if (fields['TO'] == location) {
      netQty += qty;
    }
  }

  String sign = netQty >= 0 ? '+' : '';
  return "LOC:$location|SKU:$sku|NET:$sign$netQty";
}

@pragma('vm:entry-point')
void main() {
  assert(computeLocationNetTransfer("FROM:A1|TO:B2|SKU:WIDGET|QTY:100", "WIDGET", "B2") == "LOC:B2|SKU:WIDGET|NET:+100");
  assert(computeLocationNetTransfer("FROM:B2|TO:C3|SKU:WIDGET|QTY:50", "WIDGET", "B2") == "LOC:B2|SKU:WIDGET|NET:-50");
  assert(computeLocationNetTransfer("", "WIDGET", "A1") == "LOC:A1|SKU:WIDGET|NET:+0");
  print('All tests passed!');
}

