List<String> countWaysToFillPlaylist(List<int> songDurations, int targetDuration) {
  if (targetDuration < 0) return [];
  List<int> dp = List.filled(targetDuration + 1, 0);
  dp[0] = 1;
  for (int d in songDurations) {
    if (d <= 0) continue;
    for (int t = d; t <= targetDuration; t++) {
      dp[t] += dp[t - d];
    }
  }
  List<String> result = [];
  for (int t = 0; t <= targetDuration; t++) {
    if (dp[t] > 0) {
      result.add("${t}s: ${dp[t]} ${dp[t] == 1 ? 'way' : 'ways'}");
    }
  }
  return result;
}

