  assert(parseHashBucketSpec("3:5") == "[3:5]");
  assert(parseHashBucketSpec("1:3..5") == "[1:3,2:3,3:3,4:3,5:3]");
  assert(parseHashBucketSpec("") == "[]");
  print('All tests passed!');
}

