List<int> parseHandWithSuitBonus(String hand) {
  if (hand.isEmpty) return [];
  final cards = hand.split(' ');
  final suitCounts = <String, int>{};
  for (final card in cards) {
    if (card.isEmpty) continue;
    final suit = card[card.length - 1];
    suitCounts[suit] = (suitCounts[suit] ?? 0) + 1;
  }
  final result = <int>[];
  for (final card in cards) {
    if (card.isEmpty) continue;
    final rankStr = card.substring(0, card.length - 1);
    final suit = card[card.length - 1];
    int rankValue;
    switch (rankStr) {
      case 'A': rankValue = 14; break;
      case 'K': rankValue = 13; break;
      case 'Q': rankValue = 12; break;
      case 'J': rankValue = 11; break;
      case 'T': rankValue = 10; break;
      default: rankValue = int.parse(rankStr); break;
    }
    result.add(rankValue + suitCounts[suit]!);
  }
  return result;
}

