Map<String, int> computeIntervalBucketHashStats(List<List<int>> intervals, int bucketSize) {
  final result = <String, int>{};
  if (intervals.isEmpty || bucketSize <= 0) return result;

  final bucketIndices = <int>{};
  for (final interval in intervals) {
    final s = interval[0];
    final e = interval[1];
    if (s > e || s < 0) continue;
    for (int b = s ~/ bucketSize; b <= e ~/ bucketSize; b++) {
      bucketIndices.add(b);
    }
  }

  for (final b in bucketIndices) {
    final bs = b * bucketSize;
    final be = bs + bucketSize - 1;
    final prefix = 'B$bs-$be';
    int count = 0, days = 0, full = 0;

    for (final interval in intervals) {
      final s = interval[0];
      final e = interval[1];
      if (s > e || s < 0) continue;

      if (s <= be && e >= bs) {
        count++;
        final os = s > bs ? s : bs;
        final oe = e < be ? e : be;
        days += oe - os + 1;
        if (s <= bs && e >= be) {
          full++;
        }
      }
    }

    result['${prefix}_count'] = count;
    result['${prefix}_days'] = days;
    result['${prefix}_full'] = full;
  }

  return result;
}

