@pragma('vm:entry-point')
bool isTelemetryStable(List<double> samples) {
  Map<double, int> freq = {};
  for (double s in samples) {
    freq[s] = (freq[s] ?? 0) + 1;
  }
  if (freq.length <= 1) return true;
  Set<int> freqSet = freq.values.toSet();
  if (freqSet.length == 1) return true;
  List<double> keys = freq.keys.toList();
  for (double key in keys) {
    int count = freq[key]!;
    if (count == 1) {
      Map<double, int> adjusted = Map<double, int>.from(freq);
      adjusted.remove(key);
      if (adjusted.values.toSet().length == 1) return true;
    } else {
      Map<double, int> adjusted = Map<double, int>.from(freq);
      adjusted[key] = count - 1;
      if (adjusted.values.toSet().length == 1) return true;
    }
  }
  return false;
}

