@pragma('vm:entry-point')
bool isMazeWallConsistent(String mazeStr) {
  if (mazeStr.isEmpty) return true;
  List<String> rows = mazeStr.split(';');
  int numCols = -1;
  List<List<int>> grid = [];
  const String wallAlphabet = 'abcdefghijklmnop';
  for (String row in rows) {
    List<String> cells = row.split('|');
    if (numCols == -1) {
      numCols = cells.length;
    } else if (cells.length != numCols) {
      return false;
    }
    List<int> rowBits = [];
    for (String cell in cells) {
      if (cell.length != 1) return false;
      int idx = wallAlphabet.indexOf(cell);
      if (idx == -1) return false;
      rowBits.add(idx);
    }
    grid.add(rowBits);
  }
  if (numCols <= 0 || grid.isEmpty) return true;
  int numRows = grid.length;
  const int N = 1, E = 2, S = 4, W = 8;
  for (int r = 0; r < numRows; r++) {
    for (int c = 0; c < numCols; c++) {
      int bits = grid[r][c];
      if (r > 0) {
        bool hasN = (bits & N) != 0;
        bool aboveHasS = (grid[r - 1][c] & S) != 0;
        if (hasN != aboveHasS) return false;
      }
      if (c > 0) {
        bool hasW = (bits & W) != 0;
        bool leftHasE = (grid[r][c - 1] & E) != 0;
        if (hasW != leftHasE) return false;
      }
    }
  }
  return true;
}

@pragma('vm:entry-point')
void main() {
  assert(isMazeWallConsistent("") == true);
  assert(isMazeWallConsistent("a") == true);
  assert(isMazeWallConsistent("a|a;f|a") == false);
