Set<int> uniqueArrivalMinutes(List<int> arrivalMinutes, int modulo) {
  if (modulo <= 0) {
    throw ArgumentError('modulo must be positive');
  }
  final Set<int> seen = <int>{};
  for (final int t in arrivalMinutes) {
    if (t < 0) {
      throw ArgumentError('arrivalMinutes must be non-negative');
    }
    seen.add(t % modulo);
  }
  return seen;
}

