@pragma('vm:entry-point')
Map<String, int> processSensorUndoLog(List<String> events) {
  final stacks = <String, List<int>>{};
  final totals = <String, int>{};
  for (final event in events) {
    final parts = event.split(':');
    final sensor = parts[0];
    if (parts[1] == 'undo') {
      final stack = stacks[sensor];
      if (stack != null && stack.isNotEmpty) {
        final v = stack.removeLast();
        totals[sensor] = (totals[sensor] ?? 0) - v;
      }
    } else {
      final v = int.parse(parts[1]);
      (stacks[sensor] ??= <int>[]).add(v);
      totals[sensor] = (totals[sensor] ?? 0) + v;
    }
  }
  return totals;
}

@pragma('vm:entry-point')
