@pragma('vm:entry-point')
double longestBalancedPlaylistAverage(List<double> vibes, double maxVariance) {
  if (vibes.isEmpty) return 0.0;
  int bestStart = 0;
  int bestEnd = 0;
  int left = 0;
  for (int right = 0; right < vibes.length; right++) {
    while (left <= right) {
      double mn = vibes[left];
      double mx = vibes[left];
      for (int i = left; i <= right; i++) {
        if (vibes[i] < mn) mn = vibes[i];
        if (vibes[i] > mx) mx = vibes[i];
      }
      if (mx - mn <= maxVariance) break;
      left++;
    }
    if (right - left > bestEnd - bestStart) {
      bestStart = left;
      bestEnd = right;
    }
  }
  double sum = 0.0;
  for (int i = bestStart; i <= bestEnd; i++) {
    sum += vibes[i];
  }
  return sum / (bestEnd - bestStart + 1);
}

@pragma('vm:entry-point')
void main() {
  assert(longestBalancedPlaylistAverage([2.0, 4.0, 4.0, 2.0], 2.0) == 3.0);
  assert(longestBalancedPlaylistAverage([7.5], 0.0) == 7.5);
  assert(longestBalancedPlaylistAverage(<double>[], 1.0) == 0.0);
