Set<int> sidingEvictionMinutes(int capacity, List<int> arrivals) {
  final stack = <int>[];
  final evictions = <int>{};
  for (final minute in arrivals) {
    if (stack.length >= capacity) {
      stack.removeLast();
      evictions.add(minute);
