List<String> routePickSequence(int depotX, int depotY, List<int> itemXs, List<int> itemYs, List<String> itemLabels) {
  if (itemLabels.isEmpty) return <String>[];
  List<MapEntry<int, String>> entries = [];
  for (int i = 0; i < itemLabels.length; i++) {
    int dist = (itemXs[i] - depotX).abs() + (itemYs[i] - depotY).abs();
    entries.add(MapEntry(dist, itemLabels[i]));
  }
  entries.sort((a, b) {
    int cmp = a.key.compareTo(b.key);
    if (cmp != 0) return cmp;
    return a.value.compareTo(b.value);
  });
  return entries.map((e) => e.value).toList();
}

