double aridityRatio(List<List<double>> grid, double threshold) {
  if (grid.isEmpty) return 0.0;
  int totalCells = 0;
  int dryCells = 0;
  for (final row in grid) {
    for (final moisture in row) {
      totalCells += 1;
      if (moisture <= threshold) {
        dryCells += 1;
      }
    }
  }
  if (totalCells == 0) return 0.0;
  return dryCells / totalCells;
}

