@pragma('vm:entry-point')
bool validateContainerStacking(List<List<int>> manifest, int maxImbalance) {
  if (manifest.isEmpty || manifest[0].isEmpty) return true;
  int rows = manifest.length;
  int cols = manifest[0].length;
  for (int r = 0; r < rows - 1; r++) {
    for (int c = 0; c < cols; c++) {
      if (manifest[r][c] != 0 && manifest[r + 1][c] == 0) return false;
    }
  }
  List<int> colWeights = List.filled(cols, 0);
  for (int c = 0; c < cols; c++) {
    for (int r = 0; r < rows; r++) {
      colWeights[c] += manifest[r][c];
    }
  }
  int minW = colWeights[0], maxW = colWeights[0];
  for (int c = 1; c < cols; c++) {
    if (colWeights[c] < minW) minW = colWeights[c];
    if (colWeights[c] > maxW) maxW = colWeights[c];
  }
  return maxW - minW <= maxImbalance;
}

@pragma('vm:entry-point')
void main() {
  assert(validateContainerStacking([], 5) == true);
  assert(validateContainerStacking([[0, 0], [0, 0], [5, 5]], 0) == true);
  assert(validateContainerStacking([[1], [0]], 0) == false);
  print('All tests passed!');
}

