@pragma('vm:entry-point')
List<String> formatUniqueCreditEntries(List<String> entries) {
  List<double> credits = [];
  for (var entry in entries) {
    if (entry.startsWith('credit ')) {
      var parts = entry.split(' ');
      if (parts.length == 2) {
        var amt = double.tryParse(parts[1]);
        if (amt != null && amt > 0) {
          bool seen = false;
          for (var c in credits) {
            if (c == amt) {
              seen = true;
              break;
            }
          }
          if (!seen) {
            credits.add(amt);
          }
        }
      }
    }
  }
  credits.sort((a, b) => b.compareTo(a));
  List<String> result = [];
  for (var c in credits) {
    result.add('credit ' + c.toStringAsFixed(2));
  }
  return result;
}

@pragma('vm:entry-point')
