@pragma('vm:entry-point')
double calculateRecursivePacketOverhead(List<int> packetSizes) {
  if (packetSizes.isEmpty) return 0.0;
  if (packetSizes.length == 1) return packetSizes[0].toDouble() / 2.0;
  int mid = packetSizes.length ~/ 2;
  List<int> left = packetSizes.sublist(0, mid);
  List<int> right = packetSizes.sublist(mid);
  double leftCost = calculateRecursivePacketOverhead(left);
  double rightCost = calculateRecursivePacketOverhead(right);
  double total = leftCost + rightCost;
  double diff = (leftCost - rightCost).abs();
  if (diff > 0.0) {
    total += diff / 4.0;
  }
  return total;
}

