  assert(calculateRecursivePacketOverhead([]) == 0.0);
  assert(calculateRecursivePacketOverhead([4]) == 2.0);
  assert(calculateRecursivePacketOverhead([2, 2]) == 2.0);
  print('All tests passed!');
}

