List<String> simulateTelemetryUndoStack(List<String> logs) {
  List<String> stack = [];
  List<List<String>> history = [];
  for (String entry in logs) {
    if (entry == 'undo') {
      if (stack.isNotEmpty) {
        stack.removeLast();
      }
    } else if (entry == 'snapshot') {
      history.add(List.from(stack));
    } else if (entry.startsWith('sample:')) {
      String val = entry.substring(7);
      if (val.isNotEmpty && (val.endsWith('.0') || val.endsWith('.5'))) {
        stack.add(val);
      }
    } else if (entry == 'rollback') {
      if (history.isNotEmpty) {
        stack = List.from(history.removeLast());
      } else {
        stack.clear();
      }
    }
  }
  return stack;
}

