Set<int> processPendingShipments(List<int> shipmentCodes) {
  List<int> stack = [];
  Set<int> pending = {};
  for (int code in shipmentCodes) {
    if (code > 0) {
      stack.add(code);
    } else {
      if (stack.isNotEmpty && stack.last == -code) {
        stack.removeLast();
      } else {
        pending.add(code);
      }
    }
  }
  pending.addAll(stack);
  return pending;
}

