String findOptimalPassWindows(List<int> startTimes, List<int> endTimes) {
  int n = startTimes.length;
  String best = "";
  int maxCount = 0;
  void backtrack(int idx, int lastEnd, List<int> path) {
    if (path.length > maxCount) {
      maxCount = path.length;
      best = path.join('-');
    }
    for (int i = idx; i < n; i++) {
      if (startTimes[i] >= lastEnd) {
        path.add(i);
        backtrack(i + 1, endTimes[i], path);
        path.removeLast();
      }
    }
  }
  backtrack(0, -1000000000, []);
  return best;
}

