List<String> sortMazeCellsByPriority(List<String> cells, int targetRow, int targetCol) {
  List<String> sorted = List.from(cells);
  sorted.sort((a, b) {
    List<int> parse(String s) {
      List<String> parts = s.split(',');
      return [int.parse(parts[0]), int.parse(parts[1])];
    }
    List<int> pa = parse(a);
    List<int> pb = parse(b);
    int da = (pa[0] - targetRow).abs() + (pa[1] - targetCol).abs();
    int db = (pb[0] - targetRow).abs() + (pb[1] - targetCol).abs();
    if (da != db) {
      return da.compareTo(db);
    }
    if (pa[0] != pb[0]) {
      return pa[0].compareTo(pb[0]);
    }
    return pa[1].compareTo(pb[1]);
  });
  return sorted;
}

