Map<String, int> computeRowRunEncoding(String row) {
  if (row.isEmpty) return {};
  final result = <String, int>{};
  int i = 0;
  while (i < row.length) {
    final char = row[i];
    int j = i;
    while (j < row.length && row[j] == char) {
      j++;
    }
    final length = j - i;
    result['$char$i'] = length;
    i = j;
  }
  return result;
}

