Map<String, int> categorizeCentRoundings(List<double> amounts) {
  Map<String, int> counts = {'rounded_up': 0, 'rounded_down': 0, 'exact': 0};
  for (double amount in amounts) {
    double cents = amount * 100;
    int rounded;
    if (cents % 1 == 0.5) {
      rounded = cents > 0 ? (cents + 0.5).toInt() : (cents - 0.5).toInt();
    } else {
      rounded = cents.round();
    }
    if (rounded > cents) {
      counts['rounded_up'] = counts['rounded_up']! + 1;
    } else if (rounded < cents) {
      counts['rounded_down'] = counts['rounded_down']! + 1;
    } else {
      counts['exact'] = counts['exact']! + 1;
    }
  }
  return counts;
}

