@pragma('vm:entry-point')
double computeAverageRequestedFloor(String requests) {
  if (requests.isEmpty) return 0.0;
  List<String> tokens = requests.split(',');
  double sum = 0.0;
  int count = 0;
  for (String token in tokens) {
    String trimmed = token.trim();
    if (trimmed.isEmpty) continue;
    String numStr = '';
    for (int i = 0; i < trimmed.length; i++) {
      String ch = trimmed[i];
      if (ch == 'U' || ch == 'D') {
        numStr = trimmed.substring(0, i);
        break;
      }
    }
    if (numStr.isNotEmpty) {
      int floor = int.parse(numStr);
      if (floor > 0) {
        sum += floor;
        count++;
      }
    }
  }
  if (count == 0) return 0.0;
  return sum / count;
}

@pragma('vm:entry-point')
void main() {
  assert(computeAverageRequestedFloor('1U,3D') == 2.0);
  assert(computeAverageRequestedFloor('') == 0.0);
  print('All tests passed!');
}

