@pragma('vm:entry-point')
Map<String, int> sortedCardPositions(List<String> cards, String suitOrder) {
  // Each card is rank + suit letter, e.g. "10H", "AS", "2C".
  // Ranks: 2-10 numeric, J=11, Q=12, K=13, A=14.
  // suitOrder gives suit precedence, e.g. "CHSD" means Clubs first.
  int rankValue(String card) {
    String r = card.substring(0, card.length - 1);
    if (r == 'J') return 11;
    if (r == 'Q') return 12;
    if (r == 'K') return 13;
    if (r == 'A') return 14;
    return int.parse(r);
  }
  List<String> sorted = List<String>.from(cards);
  sorted.sort((a, b) {
    int sa = suitOrder.indexOf(a[a.length - 1]);
    int sb = suitOrder.indexOf(b[b.length - 1]);
    if (sa != sb) return sa - sb;
    return rankValue(a) - rankValue(b);
  });
  Map<String, int> positions = {};
  for (int i = 0; i < sorted.length; i++) {
    positions[sorted[i]] = i;
  }
  return positions;
}

@pragma('vm:entry-point')
