Set<int> decodeFrequentPacketSizes(String encoded, int minCount) {
  if (encoded.isEmpty) return <int>{};
  final totals = <int, int>{};
  for (final part in encoded.split(',')) {
    final pieces = part.split('x');
    final count = int.parse(pieces[0]);
    final size = int.parse(pieces[1]);
    totals[size] = (totals[size] ?? 0) + count;
  }
  final result = <int>{};
  totals.forEach((size, c) {
    if (c >= minCount) result.add(size);
  });
  return result;
}

