@pragma('vm:entry-point')
double decodeBucketLoadFactor(String encoded) {
  // Encoded hash-table bucket counts as run-length segments "RxC"
  // separated by commas: R consecutive buckets each holding C entries.
  // Returns average entries per bucket, 0.0 for empty input,
  // or -1.0 if the encoding is malformed or a run length is zero.
  if (encoded.isEmpty) return 0.0;
  var totalBuckets = 0;
  var totalEntries = 0;
  for (final seg in encoded.split(',')) {
    final parts = seg.split('x');
    if (parts.length != 2 || parts[0].isEmpty || parts[1].isEmpty) {
      return -1.0;
    }
    var run = 0;
    for (var i = 0; i < parts[0].length; i++) {
      final d = parts[0].codeUnitAt(i) - 48;
      if (d < 0 || d > 9) return -1.0;
      run = run * 10 + d;
    }
    var count = 0;
    for (var i = 0; i < parts[1].length; i++) {
      final d = parts[1].codeUnitAt(i) - 48;
      if (d < 0 || d > 9) return -1.0;
      count = count * 10 + d;
    }
    if (run == 0) return -1.0;
    totalBuckets += run;
    totalEntries += run * count;
  }
  return totalEntries / totalBuckets;
}

@pragma('vm:entry-point')
void main() {
  assert(decodeBucketLoadFactor('2x3,2x1') == 2.0);
  assert(decodeBucketLoadFactor('') == 0.0);
  assert(decodeBucketLoadFactor('4x1,4x0') == 0.5);
