@pragma('vm:entry-point')
int runThermostatSchedule(String program, int initialTemp) {
  // Grammar: sequence of commands with no separators.
  //   S<digits>  set target temperature
  //   +<digits>  raise temperature
  //   -<digits>  lower temperature
  //   H          hold (ignore S/+/- until resume)
  //   R          resume
  // Returns final temperature, or -1 on any malformed input.
  int temp = initialTemp;
  bool hold = false;
  int i = 0;
  while (i < program.length) {
    String c = program[i];
    if (c == 'H') {
      hold = true;
      i++;
    } else if (c == 'R') {
      hold = false;
      i++;
    } else if (c == 'S' || c == '+' || c == '-') {
      i++;
      int start = i;
      while (i < program.length &&
          program.codeUnitAt(i) >= 48 &&
          program.codeUnitAt(i) <= 57) {
        i++;
      }
      if (start == i) return -1;
      int value = int.parse(program.substring(start, i));
      if (!hold) {
        if (c == 'S') {
          temp = value;
        } else if (c == '+') {
          temp += value;
        } else {
          temp -= value;
        }
      }
    } else {
      return -1;
    }
  }
  return temp;
}

@pragma('vm:entry-point')
void main() {
  assert(runThermostatSchedule('S70+5-3', 65) == 72);
  assert(runThermostatSchedule('+10H+5R-2', 60) == 68);
  assert(runThermostatSchedule('S', 70) == -1);
  print('All tests passed!');
}

