@pragma('vm:entry-point')
String dominantChannelPerRow(List<List<List<int>>> image, int minBrightness) {
  final buffer = StringBuffer();
  for (final row in image) {
    int r = 0;
    int g = 0;
    int b = 0;
    bool any = false;
    for (final px in row) {
      final brightness = px[0] + px[1] + px[2];
      if (brightness >= minBrightness) {
        any = true;
        r += px[0];
        g += px[1];
        b += px[2];
      }
    }
    if (!any) {
      buffer.write('-');
    } else if (r >= g && r >= b) {
      buffer.write('R');
    } else if (g >= b) {
      buffer.write('G');
    } else {
      buffer.write('B');
    }
  }
  return buffer.toString();
}

@pragma('vm:entry-point')
void main() {
  assert(dominantChannelPerRow([[[255, 0, 0], [200, 10, 10]], [[0, 255, 0], [10, 200, 10]]], 0) == 'RG');
  assert(dominantChannelPerRow([[[1, 1, 1]]], 100) == '-');
  assert(dominantChannelPerRow([], 0) == '');
