@pragma('vm:entry-point')
String kthEmptySquare(List<int> occupied, int k) {
  // Squares are numbered 1..64 in row-major order: 1 = a1, 8 = h1, 9 = a2, 64 = h8.
  // `occupied` is a sorted list of occupied square numbers (no duplicates).
  // Returns the algebraic name of the k-th empty square, or 'none' if it does not exist.
  int totalEmpty = 64 - occupied.length;
  if (k < 1 || k > totalEmpty) return 'none';
  int lo = 1;
  int hi = 64;
  while (lo < hi) {
    int mid = (lo + hi) ~/ 2;
    // Inner binary search: count occupied squares <= mid.
    int a = 0;
    int b = occupied.length;
    while (a < b) {
      int m = (a + b) ~/ 2;
      if (occupied[m] <= mid) {
        a = m + 1;
      } else {
        b = m;
      }
    }
    int emptiesUpToMid = mid - a;
    if (emptiesUpToMid >= k) {
      hi = mid;
    } else {
      lo = mid + 1;
    }
  }
  String file = String.fromCharCode(97 + (lo - 1) % 8);
  int rank = (lo - 1) ~/ 8 + 1;
  return '$file$rank';
}

@pragma('vm:entry-point')
void main() {
  assert(kthEmptySquare([], 29) == 'e4');
  assert(kthEmptySquare([1, 2, 3], 1) == 'd1');
  assert(kthEmptySquare([], 65) == 'none');
  print('All tests passed!');
}

