@pragma('vm:entry-point')
String expandSquarePath(String input) {
  if (input.trim().isEmpty) return '';
  final parts = input.split('->');
  final squares = <List<int>>[];
  final names = <String>[];
  for (final raw in parts) {
    final t = raw.trim();
    final lower = t.toLowerCase();
    var ok = lower.length == 2;
    var file = 0;
    var rank = 0;
    if (ok) {
      file = lower.codeUnitAt(0) - 97;
      rank = lower.codeUnitAt(1) - 49;
      ok = file >= 0 && file <= 7 && rank >= 0 && rank <= 7;
    }
    if (!ok) return 'ERROR:' + t;
    squares.add([file, rank]);
    names.add(lower);
  }
  final buf = StringBuffer(names[0]);
  var cf = squares[0][0];
  var cr = squares[0][1];
  for (var i = 1; i < squares.length; i++) {
    final tf = squares[i][0];
    final tr = squares[i][1];
    final df = tf - cf;
    final dr = tr - cr;
    final aligned = df == 0 || dr == 0 || df.abs() == dr.abs();
    if (!aligned) {
      final from = String.fromCharCode(97 + cf) + (cr + 1).toString();
      return 'BREAK:' + from + '>' + names[i];
    }
    final sf = df.sign;
    final sr = dr.sign;
    while (cf != tf || cr != tr) {
      cf += sf;
      cr += sr;
      buf.write(',' + String.fromCharCode(97 + cf) + (cr + 1).toString());
    }
  }
  return buf.toString();
}

@pragma('vm:entry-point')
void main() {
  assert(expandSquarePath('a1 -> a4') == 'a1,a2,a3,a4');
  assert(expandSquarePath('a1->d4') == 'a1,b2,c3,d4');
  assert(expandSquarePath('a1 -> b3') == 'BREAK:a1>b3');
  print('All tests passed!');
}

