@pragma('vm:entry-point')
Map<String, int> alignThermostatSchedules(List<int> cycleMinutes) {
  // Each zone's thermostat re-runs its heating cycle every cycleMinutes[i] minutes.
  // Returns:
  //  'syncMinutes'  : first minute (> 0) when every zone starts a cycle together (lcm)
  //  'commonStep'   : largest minute interval dividing every cycle length (gcd)
  //  'totalCycles'  : total cycle starts across all zones up to the sync moment
  if (cycleMinutes.isEmpty) {
    return {'syncMinutes': 0, 'commonStep': 0, 'totalCycles': 0};
  }
  int gcd(int a, int b) {
    while (b != 0) {
      final t = a % b;
      a = b;
      b = t;
    }
    return a;
  }
  int g = cycleMinutes[0];
  int l = cycleMinutes[0];
  for (int i = 1; i < cycleMinutes.length; i++) {
    final c = cycleMinutes[i];
    g = gcd(g, c);
    l = l ~/ gcd(l, c) * c;
  }
  int total = 0;
  for (final c in cycleMinutes) {
    total += l ~/ c;
  }
  return {'syncMinutes': l, 'commonStep': g, 'totalCycles': total};
}

@pragma('vm:entry-point')
void main() {
  assert(alignThermostatSchedules([4, 6])['syncMinutes'] == 12);
  assert(alignThermostatSchedules([2, 3, 4])['totalCycles'] == 13);
  assert(alignThermostatSchedules([5, 10, 20])['commonStep'] == 5);
  print('All tests passed!');
}

