@pragma('vm:entry-point')
bool hasDominantFaceStreak(List<List<int>> rounds, int streak) {
  // A round's "dominant face" is the die value with a strictly highest
  // frequency in that round. Returns true if the same face is dominant
  // in at least `streak` consecutive rounds.
  if (streak <= 0) return true;
  int current = 0;
  int lastFace = -1;
  for (final round in rounds) {
    final counts = <int, int>{};
    for (final die in round) {
      counts[die] = (counts[die] ?? 0) + 1;
    }
    int bestFace = -1;
    int bestCount = 0;
    bool tie = false;
    counts.forEach((face, c) {
      if (c > bestCount) {
        bestCount = c;
        bestFace = face;
        tie = false;
      } else if (c == bestCount) {
        tie = true;
      }
    });
    if (bestFace == -1 || tie) {
      current = 0;
      lastFace = -1;
    } else if (bestFace == lastFace) {
      current += 1;
    } else {
      lastFace = bestFace;
      current = 1;
    }
    if (current >= streak) return true;
  }
  return false;
}

@pragma('vm:entry-point')
void main() {
  assert(hasDominantFaceStreak([[3, 3, 1], [3, 2, 3], [3, 3, 5]], 3) == true);
  assert(hasDominantFaceStreak([[2, 2, 5, 5]], 1) == false);
  assert(hasDominantFaceStreak([[4, 4, 1], [2, 2, 3], [4, 4, 5]], 2) == false);
  print('All tests passed!');
}

