@pragma('vm:entry-point')
double averageQrModulesScanned(int startDay, int endDay, int periodDays, int modulesPerScan) {
  // A QR kiosk rescans its code on startDay and then every periodDays days,
  // refreshing modulesPerScan dark modules per scan. Over the inclusive day
  // interval [startDay, endDay], return the average modules refreshed per day.
  if (endDay < startDay) return 0.0;
  int total = 0;
  for (int d = startDay; d <= endDay; d++) {
    if ((d - startDay) % periodDays == 0) {
      total += modulesPerScan;
    }
  }
  int days = endDay - startDay + 1;
  return total / days;
}

@pragma('vm:entry-point')
