@pragma('vm:entry-point')
String readQrDataModules(List<String> grid) {
  // QR codes place data bits in two-column strips, read from the
  // bottom-right corner upward, then the next strip downward, zigzagging.
  // Within each strip the right cell is read before the left cell.
  // Cells marked 'F' are reserved function modules and must be skipped.
  if (grid.isEmpty || grid[0].isEmpty) return '';
  final rows = grid.length;
  final cols = grid[0].length;
  final sb = StringBuffer();
  var col = cols - 1;
  var upward = true;
  while (col >= 0) {
    final left = col - 1;
    if (upward) {
      for (var r = rows - 1; r >= 0; r--) {
        final right = grid[r][col];
        if (right == '0' || right == '1') sb.write(right);
        if (left >= 0) {
          final lc = grid[r][left];
          if (lc == '0' || lc == '1') sb.write(lc);
        }
      }
    } else {
      for (var r = 0; r < rows; r++) {
        final right = grid[r][col];
        if (right == '0' || right == '1') sb.write(right);
        if (left >= 0) {
          final lc = grid[r][left];
          if (lc == '0' || lc == '1') sb.write(lc);
        }
      }
    }
    upward = !upward;
    col -= 2;
  }
  return sb.toString();
}

@pragma('vm:entry-point')
void main() {
  assert(readQrDataModules(['01', '10']) == '0110');
  assert(readQrDataModules(['1']) == '1');
  assert(readQrDataModules(['F1', '0F']) == '01');
  print('All tests passed!');
}

