Map<String, int> scanTideReadings(String readings) {
  int level = 0;
  int peaks = 0;
  int invalid = 0;

  for (int i = 0; i < readings.length; i++) {
    String ch = readings[i];
    if (ch == 'H') {
      level++;
      if (level >= 3) peaks++;
    } else if (ch == 'L') {
      if (level > 0) level--;
    } else if (ch != 'S') {
      invalid++;
    }
  }

  return {'level': level, 'peaks': peaks, 'invalid': invalid};
}

