@pragma('vm:entry-point')
int overlappingDeckArea(List<int> deckRects) {
  if (deckRects.isEmpty) {
    return 0;
  }

  final xs = <int>[];
  final ys = <int>[];

  for (int i = 0; i < deckRects.length; i += 4) {
    final x = deckRects[i];
    final y = deckRects[i + 1];
    final w = deckRects[i + 2];
    final h = deckRects[i + 3];

    if (w <= 0 || h <= 0) {
      continue;
    }

    xs.add(x);
    xs.add(x + w);
    ys.add(y);
    ys.add(y + h);
  }

  if (xs.isEmpty || ys.isEmpty) {
    return 0;
  }

  xs.sort();
  ys.sort();

  final uniqueX = <int>[];
  final uniqueY = <int>[];

  for (final v in xs) {
    if (uniqueX.isEmpty || uniqueX.last != v) {
      uniqueX.add(v);
    }
  }

  for (final v in ys) {
    if (uniqueY.isEmpty || uniqueY.last != v) {
      uniqueY.add(v);
    }
  }

  int overlapArea = 0;

  for (int xi = 0; xi < uniqueX.length - 1; xi++) {
    for (int yi = 0; yi < uniqueY.length - 1; yi++) {
      final left = uniqueX[xi];
      final right = uniqueX[xi + 1];
      final bottom = uniqueY[yi];
      final top = uniqueY[yi + 1];

      int covering = 0;

      for (int i = 0; i < deckRects.length; i += 4) {
        final x = deckRects[i];
        final y = deckRects[i + 1];
        final w = deckRects[i + 2];
        final h = deckRects[i + 3];

        if (w > 0 && h > 0 &&
            x <= left && x + w >= right &&
            y <= bottom && y + h >= top) {
          covering++;
        }
      }

      if (covering >= 2) {
        overlapArea += (right - left) * (top - bottom);
      }
    }
  }

  return overlapArea;
}

@pragma('vm:entry-point')
void main() {
  assert(overlappingDeckArea([0, 0, 4, 4, 2, 2, 4, 4]) == 4);
  assert(overlappingDeckArea([0, 0, 3, 3, 1, 1, 3, 3, 2, 2, 3, 3]) == 7);
  assert(overlappingDeckArea([]) == 0);
  print('All tests passed!');
}

