void main() {
  assert(decodeCompressedMinuteBoard('1D') == '45#45');
  assert(decodeCompressedMinuteBoard('2A1C1E3B') == '00,00,30|15,15,15#75');
  assert(decodeCompressedMinuteBoard('') == '#00');
  print('All tests passed!');
}

