int sharedShuffleGroupSize(List<int> deckSizes) {
  if (deckSizes.isEmpty) {
    return 0;
  }

  int gcd(int a, int b) {
    while (b != 0) {
      int temp = b;
      b = a % b;
      a = temp;
    }
    return a.abs();
  }

  int result = deckSizes[0];
  for (int size in deckSizes.skip(1)) {
    result = gcd(result, size);
  }
  return result;
}

