Set<int> flaggedTelemetryBands(List<List<int>> samples, int jumpLimit) {
  Set<int> flagged = <int>{};

  for (int r = 0; r < samples.length; r++) {
    int abruptChanges = 0;
    bool hasEcho = false;

    for (int c = 0; c < samples[r].length; c++) {
      int current = samples[r][c];

      if (c + 1 < samples[r].length) {
        int horizontalGap = (current - samples[r][c + 1]).abs();
        if (horizontalGap >= jumpLimit) {
          abruptChanges++;
        }
      }

      if (r + 1 < samples.length && c < samples[r + 1].length) {
        int below = samples[r + 1][c];

        if (current == below) {
          hasEcho = true;
        }

        int verticalGap = (current - below).abs();
        if (verticalGap >= jumpLimit) {
          abruptChanges++;
        }
      }
    }

    if (abruptChanges >= 2 && hasEcho) {
      flagged.add(r);
    }
  }

  return flagged;
}

