  expect(candidate(['0,0,5,5','5,0,8,5']), '40@1');
  expect(candidate(['5,5,1,1','2,2,2,9']), '16@1');
  expect(candidate(['0,0,4,4','1,1,5,3','2,0,3,5']), '19@3');
