void main() {
  assert(rgbPrimeResidueBalance([], 5) == 0.0);
  assert(rgbPrimeResidueBalance([0x000000], 5) == 0.5);
  assert(rgbPrimeResidueBalance([0xFFFFFF], 5) == -0.5);
  print('All tests passed!');
}

