Map<String, int> tallyInventoryItems(List<String> itemNames) {
  if (itemNames.isEmpty) {
    return {};
  }
  if (itemNames.length == 1) {
    return {itemNames[0]: 1};
  }
  int mid = itemNames.length ~/ 2;
  Map<String, int> left = tallyInventoryItems(itemNames.sublist(0, mid));
  Map<String, int> right = tallyInventoryItems(itemNames.sublist(mid));
  for (String item in right.keys) {
    left[item] = (left[item] ?? 0) + right[item]!;
  }
  return left;
}

