@pragma('vm:entry-point')
bool validatesDnaFlagChecksum(String dna, int requiredMask) {
  int seenMask = 0;
  int parityMask = 0;

  for (int i = 0; i < dna.length; i++) {
    String base = dna[i];
    int bit;

    if (base == 'A') {
      bit = 1;
    } else if (base == 'C') {
      bit = 2;
    } else if (base == 'G') {
      bit = 4;
    } else if (base == 'T') {
      bit = 8;
    } else {
      return false;
    }

    seenMask |= bit;

    if (i > 0 && dna[i] == dna[i - 1]) {
      parityMask ^= bit;
    } else {
      parityMask = ((parityMask << 1) | (parityMask >> 3)) & 15;
    }
  }

  requiredMask &= 15;
  bool hasRequiredBases = (seenMask & requiredMask) == requiredMask;
  bool singleParityBit =
      parityMask != 0 && (parityMask & (parityMask - 1)) == 0;

  return hasRequiredBases && singleParityBit;
}

@pragma('vm:entry-point')
void main() {
  assert(validatesDnaFlagChecksum("AA", 1) == true);
  assert(validatesDnaFlagChecksum("AAA", 1) == false);
  assert(validatesDnaFlagChecksum("AAC", 3) == true);
