@pragma('vm:entry-point')
int roundedCentOverlapCharge(List<List<int>> rectangles) {
  Map<String, int> cellCharges = {};

  for (List<int> rect in rectangles) {
    int x1 = rect[0];
    int y1 = rect[1];
    int x2 = rect[2];
    int y2 = rect[3];
    int cents = rect[4];

    if (x2 <= x1 || y2 <= y1 || cents < 0) {
      continue;
    }

    for (int x = x1; x < x2; x++) {
      for (int y = y1; y < y2; y++) {
        String key = '$x,$y';
        int current = cellCharges[key] ?? 0;
        if (cents > current) {
          cellCharges[key] = cents;
        }
      }
    }
  }

  int total = 0;
  for (int value in cellCharges.values) {
    total += value;
  }

  int remainder = total % 5;
  if (remainder >= 3) {
    return total + (5 - remainder);
  }
  return total - remainder;
}

@pragma('vm:entry-point')
void main() {
  assert(roundedCentOverlapCharge([[0, 0, 2, 1, 7]]) == 15);
  assert(roundedCentOverlapCharge([[0, 0, 2, 2, 4], [1, 1, 3, 3, 9]]) == 45);
  assert(roundedCentOverlapCharge([]) == 0);
  print('All tests passed!');
}

