@pragma('vm:entry-point')
double spellEditInfluenceArea(List<int> editRows, List<int> editCols, int radius) {
  if (editRows.length != editCols.length) {
    throw ArgumentError('Mismatched coordinate lists');
  }
  if (radius < 0) {
    throw ArgumentError('Negative radius');
  }
  if (editRows.isEmpty || radius == 0) {
    return 0.0;
  }

  final List<List<int>> rects = [];
  final Set<int> uSet = {};
  final Set<int> vSet = {};

  for (int i = 0; i < editRows.length; i++) {
    final int u = editRows[i] + editCols[i];
    final int v = editRows[i] - editCols[i];
    final int u1 = u - radius;
    final int u2 = u + radius;
    final int v1 = v - radius;
    final int v2 = v + radius;

    rects.add([u1, u2, v1, v2]);
    uSet.add(u1);
    uSet.add(u2);
    vSet.add(v1);
    vSet.add(v2);
  }

  final List<int> us = uSet.toList()..sort();
  final List<int> vs = vSet.toList()..sort();

  int doubledArea = 0;

  for (int i = 0; i < us.length - 1; i++) {
    for (int j = 0; j < vs.length - 1; j++) {
      final int midU2 = us[i] + us[i + 1];
      final int midV2 = vs[j] + vs[j + 1];
      bool covered = false;

      for (final rect in rects) {
        if (midU2 > rect[0] * 2 &&
            midU2 < rect[1] * 2 &&
            midV2 > rect[2] * 2 &&
            midV2 < rect[3] * 2) {
          covered = true;
          break;
        }
      }

      if (covered) {
        doubledArea += (us[i + 1] - us[i]) * (vs[j + 1] - vs[j]);
      }
    }
  }

  return doubledArea / 2.0;
}

@pragma('vm:entry-point')
void main() {
  assert(spellEditInfluenceArea([0], [0], 1) == 2.0);
  assert(spellEditInfluenceArea([0, 1], [0, 0], 1) == 3.0);
  assert(spellEditInfluenceArea([0, 3], [0, 0], 1) == 4.0);
  print('All tests passed!');
}

