@pragma('vm:entry-point')
bool canScaleRecipeBlend(List<int> ingredientUnits, int targetUnits, int maxRepeatedSize) {
  if (targetUnits < 0 || maxRepeatedSize < 1) {
    return false;
  }

  Map<int, int> counts = {};
  int left = 0;
  int currentTotal = 0;

  for (int right = 0; right < ingredientUnits.length; right++) {
    int value = ingredientUnits[right];
    currentTotal += value;
    counts[value] = (counts[value] ?? 0) + 1;

    while (left <= right &&
        (currentTotal > targetUnits ||
            (counts[value] ?? 0) > maxRepeatedSize)) {
      int removed = ingredientUnits[left];
      currentTotal -= removed;
      counts[removed] = (counts[removed] ?? 0) - 1;

      if (counts[removed] == 0) {
        counts.remove(removed);
      }

      left++;
    }

    if (currentTotal == targetUnits) {
      return true;
    }
  }

  return false;
}

@pragma('vm:entry-point')
void main() {
  assert(canScaleRecipeBlend([2, 3, 5, 2], 10, 1) == true);
  assert(canScaleRecipeBlend([1, 1, 1, 4], 3, 2) == false);
  assert(canScaleRecipeBlend([], 5, 1) == false);
  print('All tests passed!');
}

